-- Lliçons fixes de Morfosintaxi del C1 (botó «Aprendre lliçó»).
-- Com les del B2, cada lliçó és una adaptació didàctica de nivell C1
-- redactada a partir de:
--   - l'abast de cada contingut del C1 (Quadern C1 de la JQCV, 3.2.2), descrit en
--     20261014160000_practice_morfosintaxi_c1.sql;
--   - les regles de la Gramàtica valenciana bàsica (GVB) i de la Gramàtica normativa
--     valenciana (GNV) de l'AVL, descarregades una sola vegada en assets-src/avl/.
-- El contingut es guarda en metadata.lesson (mateix format que en el B1 i el B2). La migració de
-- continguts (20261014160000) conserva metadata.lesson si es torna a aplicar.
-- Tornar a aplicar este fitxer no canvia res més.

UPDATE public.resources r SET
  metadata = coalesce(r.metadata, '{}'::jsonb) || jsonb_build_object('lesson', l.lesson)
FROM jsonb_to_recordset($data$[
  {"type": "c1_mor_substantius", "lesson": {"intro": "Aprendràs les alternances de gènere en -e, -o i -u, el gènere dels abstractes en -or i dels noms que el castellà fa canviar, els plurals especials i invariables, els noms de doble gènere i els epicens.", "blocks": [{"title": "Femenins de -e, -o i -u", "text": "Els masculins en ***-e*** o ***-o*** àtones canvien la vocal per ***-a***: *pediatre* → *pediatra*, *monjo* → *monja*. Els acabats en ***-eu*** canvien la *u* per *a* (*europeu* → *europea*), però *jueu* i *hereu* fan *jueua* o *jueva*, *hereua* o *hereva*. Els acabats en ***-i*** o ***-u*** àtones afigen *-a* i passen a **esdrúixols**. Compte amb els femenins en **-essa**.", "table": {"head": ["masculí", "femení"], "rows": [["*pediatre*", "*pediatra*"], ["*monjo*", "*monja*"], ["*europeu*", "*europea*"], ["*individu*", "*indivídua*"], ["*rebesavi*", "*rebesàvia*"], ["*sastre*", "*sastressa*"], ["*hindú*", "*hindú* (invariable)"]]}}, {"title": "Els abstractes en -or", "text": "La majoria d'abstractes en ***-or*** són **femenins**: *la calor*, *la suor*, *la remor*, *l'olor*, *l'amargor*, *la frescor*, *la blancor*. Però n'hi ha de **masculins**: *el dolor*, *l'amor*, *l'honor*, *el color*, *el clamor*. *Esplendor* i *resplendor* són preferentment femenins, però també s'admeten en masculí.", "examples": ["Este café té **una amargor** estranya.", "Se sentia **la remor** de les ones.", "**El clamor** popular va obligar a rectificar.", "Sent **un dolor** molt intens."], "watch": [{"wrong": "un calor horrorós", "right": "una calor horrorosa"}, {"wrong": "l'amargor és molt fort", "right": "l'amargor és molt forta"}]}, {"title": "Gènere diferent del castellà", "text": "Per **interferència**, alguns noms es fan servir amb el gènere del castellà. Són **masculins** *els afores*, *el corrent*, *el deute*, *el dubte*, *els espinacs*, *el senyal*, *un avantatge*, *un estratagema*. Són **femenins** *la calor*, *la dent*, *la remor*, *una anàlisi*, *la síndrome*, *una marató*. Fixa't en l'**adjectiu**: ha de concordar.", "examples": ["Viuen **als afores** de la ciutat.", "Han tallat **el corrent** elèctric.", "Jugar a casa és **un gran avantatge**."], "watch": [{"wrong": "la corrent elèctrica", "right": "el corrent elèctric"}, {"wrong": "a les afores", "right": "als afores"}, {"wrong": "la deute pendent", "right": "el deute pendent"}]}, {"title": "Plurals especials, invariables i gràfics", "text": "Molts **aguts** manllevats fan el plural en ***-s*** i no en *-ns*: *sofàs*, *cafés*, *bisturís*, *xampús*. Són **invariables** els masculins plans en *-s* (*el llapis*, *el cactus*) i els dies de la setmana (*els dilluns*). Hi ha també **plurals gràfics**: la *-s* s'escriu però no canvia la pronúncia (*les falçs*, *els apèndixs*).", "table": {"head": ["singular", "plural"], "rows": [["*sofà*, *café*", "*sofàs*, *cafés*"], ["*cosí*, *camió*", "*cosins*, *camions*"], ["*el llapis*, *el cactus*", "*els llapis*, *els cactus*"], ["*el dilluns*", "*els dilluns*"], ["*la falç*, *la faç*", "*les falçs*, *les façs*"], ["*l'apèndix*, *l'índex*", "*els apèndixs*, *els índexs*"], ["*el sufix*, *el fax*", "*els sufixos*, *els faxos*"]]}, "watch": [{"wrong": "els llàpissos", "right": "els llapis"}, {"wrong": "els dillunsos", "right": "els dilluns"}]}, {"title": "Doble gènere, doble significat", "text": "Alguns noms canvien de **significat** segons el **gènere**. A més dels que ja coneixes (*el fi* / *la fi*, *el pols* / *la pols*), al C1 has de dominar parelles com estes:", "table": {"head": ["masculí", "femení"], "rows": [["*el capital*: diners, béns", "*la capital*: ciutat principal"], ["*el canal*: via d'aigua", "*la canal*: conducte de la teulada"], ["*el còlera*: epidèmia", "*la còlera*: irritació"], ["*el delta*: accident geogràfic", "*la delta*: lletra grega"], ["*un orde*: institució, disposició", "*una orde*: manament"], ["*el vall*: excavació", "*la vall*: terreny entre muntanyes"]]}}, {"title": "Els epicens", "text": "Els **epicens** designen amb **un sol nom** els mascles i les femelles d'una espècie. El nom **manté el seu gènere** i, si cal precisar el sexe, s'afig ***mascle*** o ***femella***. No es crea un femení nou.", "examples": ["**el fardatxo mascle** / **el fardatxo femella**", "**el rossinyol femella** cova els ous", "**la formiga mascle** té ales"], "watch": [{"wrong": "la fardatxa", "right": "el fardatxo femella"}, {"wrong": "el formigo", "right": "la formiga mascle"}]}], "remember": ["*Pediatre* / *pediatra*, *monjo* / *monja*, *europeu* / *europea*; però *sastre* / *sastressa*.", "Femenins: *la calor*, *l'amargor*, *la frescor*, *la remor*. Masculins: *el dolor*, *el clamor*, *l'amor*.", "Masculins per interferència: *els afores*, *el corrent*, *el deute*, *el dubte*, *els espinacs*.", "*Sofàs*, *cafés*; *els llapis*, *els dilluns*; *les falçs*, *els apèndixs*.", "*El capital* / *la capital*, *el còlera* / *la còlera*, *el canal* / *la canal*.", "Epicens: *el fardatxo femella*, *la formiga mascle*."], "sources": [{"gram": "GVB", "section": "16.2.2", "title": "El femení dels masculins acabats en vocal", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=16_2_2"}, {"gram": "GVB", "section": "16.2.3", "title": "Altres casos", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=16_2_3"}, {"gram": "GVB", "section": "16.3", "title": "Substantius de gènere ambigu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=16_3"}, {"gram": "GVB", "section": "16.4", "title": "El gènere com a marca semàntica", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=16_4"}, {"gram": "GVB", "section": "16.5", "title": "Vacil·lacions en el gènere d'alguns substantius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=16_5"}, {"gram": "GVB", "section": "17.2", "title": "La formació del plural", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=17_2"}, {"gram": "GVB", "section": "17.3", "title": "Substantius invariables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=17_3"}, {"gram": "GNV", "section": "10.2.2", "title": "La formació del femení a partir de masculins acabats en vocal", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=10_2_2"}, {"gram": "GNV", "section": "10.2.3", "title": "Altres casos", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=10_2_3"}, {"gram": "GNV", "section": "10.3.1", "title": "El gènere com a marca semàntica", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=10_3_1"}, {"gram": "GNV", "section": "10.3.2", "title": "Observacions sobre el gènere d'alguns substantius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=10_3_2"}, {"gram": "GNV", "section": "11.2", "title": "La formació del plural", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=11_2"}, {"gram": "GNV", "section": "11.3", "title": "Substantius invariables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=11_3"}]}},
  {"type": "c1_mor_adjectius", "lesson": {"intro": "Aprendràs els femenins amb hiat o diftong creixent, els adjectius que tenen femení a diferència del castellà, els plurals fixos, els contrastos de nombre amb el castellà i la col·locació de l'adjectiu.", "blocks": [{"title": "Hiat i diftong creixent", "text": "Els adjectius en ***-i*** o ***-u*** àtones afigen *-a* i passen a **esdrúixols**: *promiscu* → *promíscua*. Els acabats en ***-gu*** es mantenen **plans**: *ambigua*, *contigua*. Alguns en ***-ic*** fan el femení en ***-qua***: *inic* → *iniqua*. En plural, fixa't en la **dièresi**: *iniqües*, *ambigües*.", "table": {"head": ["masculí", "femení", "femení plural"], "rows": [["*promiscu*", "*promíscua*", "*promíscues*"], ["*ingenu*", "*ingènua*", "*ingènues*"], ["*ambigu*", "*ambigua*", "*ambigües*"], ["*inic*", "*iniqua*", "*iniqües*"], ["*oblic*", "*obliqua*", "*obliqües*"]]}}, {"title": "Femenins que el castellà no té", "text": "Molts adjectius que en castellà són **invariables** tenen **femení** en valencià. Entre els casos difícils: *pobre* / *pobra*, *comú* / *comuna*, *covard* / *covarda*, *mallorquí* / *mallorquina*. En canvi, *amargant* és **invariable**, com *lliure* o *salvatge*.", "table": {"head": ["masculí", "femení"], "rows": [["*verd*", "*verda*"], ["*dolç*", "*dolça*"], ["*trist*", "*trista*"], ["*pobre*", "*pobra*"], ["*comú*", "*comuna*"], ["*covard*", "*covarda*"], ["*amargant*", "*amargant*"]]}, "watch": [{"wrong": "una fruita molt dolç", "right": "una fruita molt dolça"}, {"wrong": "una gent molt pobre", "right": "una gent molt pobra"}]}, {"title": "Sempre en plural", "text": "Els ***pluralia tantum*** només s'usen en **plural**: objectes de dues parts (*les ulleres*, *les tisores*, *les alicates*), jocs (*els escacs*), malalties (*les paperes*, *les angines*) i altres noms com *les postres*, *les estovalles*, *els honoraris* o *els annals*.", "examples": ["He trencat **les ulleres**.", "Juguem **als escacs** els dissabtes.", "De **postres** hi ha flam."], "watch": [{"wrong": "el postre", "right": "les postres"}, {"wrong": "jugar a l'ajedrez", "right": "jugar als escacs"}]}, {"title": "Contrastos amb el castellà", "text": "Alguns noms i fórmules tenen en valencià un **nombre diferent** del castellà. La salutació va en **singular** (*bon dia*), *diners* va en **plural**, i molts compostos van en **singular**: *el gratacel*, *el parabrisa*, *el parafang*, *el paraigua*.", "table": {"head": ["valencià", "castellà"], "rows": [["*bon dia*, *bona nit*", "*buenos días*, *buenas noches*"], ["*els diners*", "*el dinero*"], ["*el gratacel*", "*el rascacielos*"], ["*el parabrisa*", "*el parabrisas*"], ["*el parafang*", "*el guardabarros*"], ["*les postres*", "*el postre*"]]}}, {"title": "On col·loquem l'adjectiu", "text": "L'adjectiu va normalment **darrere** del nom i en **restringix** el significat. **Davant** té un valor **afectiu** o **emfàtic**, com en els **epítets** (*la blanca neu*). Alguns van sempre davant (*un mer tràmit*, *el presumpte culpable*), i uns altres **canvien de significat** segons la posició.", "table": {"head": ["anteposat", "posposat"], "rows": [["*un pobre home*: que fa llàstima", "*un home pobre*: sense diners"], ["*una certa notícia*: determinada", "*una notícia certa*: verdadera"], ["*un nou cotxe*: un altre", "*un cotxe nou*: sense usar"], ["*una gran persona*: digna", "*una persona gran*: de mesures considerables"], ["*un alt executiu*: directiu", "*un executiu alt*: de gran alçada"]]}}], "remember": ["*Promiscu* / *promíscua*, *ingenu* / *ingènua*; però *ambigu* / *ambigua*.", "*Inic* / *iniqua* / *iniqües*; *oblic* / *obliqua* / *obliqües*.", "*Verda*, *dolça*, *trista*, *pobra*, *comuna*, *covarda*; però *amargant* és invariable.", "Sempre plurals: *les ulleres*, *els escacs*, *les postres*, *les estovalles*.", "*Bon dia*, *els diners*, *el gratacel*, *el parabrisa*, *el parafang*.", "*Un pobre home* fa llàstima; *un home pobre* no té diners."], "sources": [{"gram": "GVB", "section": "17.4", "title": "Substantius defectius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=17_4"}, {"gram": "GVB", "section": "18.1.2", "title": "Els adjectius variables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=18_1_2"}, {"gram": "GVB", "section": "18.1.3", "title": "Els adjectius invariables respecte al gènere", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=18_1_3"}, {"gram": "GVB", "section": "18.2.1", "title": "La formació del plural", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=18_2_1"}, {"gram": "GVB", "section": "18.4", "title": "La posició de l'adjectiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=18_4"}, {"gram": "GNV", "section": "11.4", "title": "Substantius defectius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=11_4"}, {"gram": "GNV", "section": "12.2.1", "title": "Els adjectius qualificatius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=12_2_1"}, {"gram": "GNV", "section": "13.2.2", "title": "La formació del femení a partir de masculins acabats en vocal", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=13_2_2"}, {"gram": "GNV", "section": "13.3", "title": "Els adjectius invariables respecte al gènere", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=13_3"}, {"gram": "GNV", "section": "14.2", "title": "La formació del plural", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=14_2"}]}},
  {"type": "c1_mor_determinants", "lesson": {"intro": "Aprendràs quan cal posar o evitar l'article (davant d'infinitius, dies, festes i topònims), com substituir l'article neutre lo en registre formal i com usar els possessius sense abusar-ne.", "blocks": [{"title": "Article i infinitiu", "text": "Davant d'un **infinitiu** no lexicalitzat, en la llengua formal **s'omet l'article**. Si cal, es pot usar ***el fet de*** o un **substantiu**. Només admeten article els infinitius que ja són **noms** (*el dinar*, *el despertar*, *els sabers*). Davant d'una **subordinada** tampoc no hi va article: *Que vingues m'agrada*.", "examples": ["**Saber** això m'alegra molt.", "**El fet de** conéixer idiomes l'ha ajudat.", "No té **els sabers** necessaris per a eixe treball."], "watch": [{"wrong": "El saber això m'alegra.", "right": "Saber això m'alegra."}, {"wrong": "El que no diga res és bon senyal.", "right": "El fet que no diga res és bon senyal."}]}, {"title": "Amb article o sense", "text": "Alguns usos són **fixos**. *Parar taula* va **sense article**. Els dies amb valor d'**immediatesa** van sense article (*vingué dilluns*), però el porten si duen **adjectiu**, **data** o valor de **freqüència**. Les festes es diuen sense article (*Nadal*, *Tots Sants*). Els noms de persona van **sense article**, i alguns topònims el porten **per tradició**.", "table": {"head": ["sense article", "amb article"], "rows": [["*Vingué dilluns.*", "*el pròxim dilluns*"], ["*Vindrà divendres.*", "*el divendres 3 de maig*"], ["*Ja s'acosta Nadal.*", "*els dimarts* (freqüència)"], ["*Parar taula.*", "*la Vall d'Uixó*, *el Marroc*"], ["*el dia de Tots Sants*", "*l'Alcora*, *el Campello*"]]}}, {"title": "Lo abstractiu: alternatives", "text": "En els registres **formals** s'evita ***lo*** amb valor **abstractiu**. Segons el cas, es reemplaça per l'article ***el***, per ***això que*** o ***allò que***, per un **substantiu abstracte** o per una altra fórmula.", "table": {"head": ["col·loquial", "formal"], "rows": [["*Lo que dius...*", "*El que dius...* / *Això que dius...*"], ["*Lo que passa és que...*", "*El cas és que...*"], ["*Lo cert és que...*", "*La veritat és que...*"], ["*Lo lleig i lo bell*", "*La lletjor i la bellesa*"], ["*per lo civil*", "*pel civil*"], ["*lo de sempre*", "*el mateix de sempre*"]]}}, {"title": "Lo intensiu: mai", "text": "El ***lo*** **intensiu** davant d'adjectiu o d'adverbi **no s'accepta en cap registre**. S'usen ***que***, ***com*** o ***tan***. Per a la idea de 'màxim possible' hi ha ***al més*** **+ adverbi + possible**, *com més... millor* i *tan... com puga*.", "examples": ["No saps **com** treballen **de** bé.", "**Tan** bonic **que** és, i no para de plorar!", "Vine **al més** prompte **possible**.", "Ho faré **tan** ràpid **com** puga."], "watch": [{"wrong": "lo bé que canta", "right": "que bé que canta / com canta de bé"}, {"wrong": "lo suficientment madur", "right": "prou madur"}, {"wrong": "lo més prompte possible", "right": "al més prompte possible"}]}, {"title": "Modismes amb lo", "text": "Molts modismes amb ***lo*** són **calcs del castellà** i s'han de substituir per expressions genuïnes. Aprén-ne les equivalències.", "table": {"head": ["calc", "forma genuïna"], "rows": [["*a lo millor*", "*potser*, *tal vegada*, *a la millor*"], ["*per lo tant*", "*per tant*"], ["*per lo menys*", "*almenys*"], ["*per lo general*", "*generalment*"], ["*per lo vist*", "*segons sembla*"], ["*en lo successiu*", "*d'ara en avant*"], ["*lo qual*", "*la qual cosa*, *cosa que*"], ["*lo mateix em dona*", "*tant me fa*, *em té igual*"]]}}, {"title": "Ús i abús dels possessius", "text": "Si la possessió es **deduïx del context**, basta l'**article**: *Renta't les mans*. El possessiu explícit és útil quan hi ha **ambigüitat**. En locucions es posposa (*darrere seu*, *en contra vostra*). Amb un **posseïdor inanimat**, la llengua formal preferix el pronom ***en*** al possessiu.", "examples": ["He portat **el** cotxe al taller.", "Caminava **darrere seu**.", "Este llibre és bo: **en** conec l'autor.", "Vam entrar al museu i **en** vam visitar una part."], "watch": [{"wrong": "Renta't les teues mans.", "right": "Renta't les mans."}, {"wrong": "darrere de seu", "right": "darrere seu / darrere d'ell"}]}], "remember": ["Davant d'infinitiu, sense article: *Saber això m'alegra*; si cal, *el fet de*.", "*Parar taula*, *vingué dilluns*, *ja s'acosta Nadal*, *el dia de Tots Sants*.", "*Lo* abstractiu, en registre formal, es reemplaça per *el*, *això que* o un substantiu.", "*Lo* intensiu mai: *que bé que canta*, *prou madur*, *al més prompte possible*.", "*Potser*, *per tant*, *almenys*, *generalment*, *la qual cosa*.", "*Renta't les mans*; amb posseïdor inanimat, *en conec l'autor*."], "sources": [{"gram": "GVB", "section": "19.2.5", "title": "L'ús de l'article definit davant dels dies de la setmana", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=19_2_5"}, {"gram": "GVB", "section": "19.2.7", "title": "L'ús de l'article definit davant d'infinitius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=19_2_7"}, {"gram": "GVB", "section": "19.2.8", "title": "L'ús de l'article definit davant d'oracions subordinades", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=19_2_8"}, {"gram": "GVB", "section": "19.5.1", "title": "Usos amb funció substantivadora", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=19_5_1"}, {"gram": "GVB", "section": "19.5.2", "title": "Altres usos", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=19_5_2"}, {"gram": "GVB", "section": "21.2.3", "title": "Alternança dels possessius i els pronoms personals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=21_2_3"}, {"gram": "GVB", "section": "21.2.4", "title": "Ús impropi dels possessius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=21_2_4"}, {"gram": "GNV", "section": "15.2.2", "title": "Observacions sobre l'ús de l'article definit", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=15_2_2"}, {"gram": "GNV", "section": "15.5", "title": "L'article neutre", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=15_5"}, {"gram": "GNV", "section": "17.2.2", "title": "Aspectes sintàctics", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=17_2_2"}, {"gram": "GNV", "section": "23.4.1", "title": "El pronom *ne*", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_4_1"}, {"gram": "GNV", "section": "28.6.2", "title": "Precisions sobre l'ús de les formes no personals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_6_2"}]}},
  {"type": "c1_mor_pronoms_febles", "lesson": {"intro": "Aprendràs a usar *en* i *hi* en totes les funcions que exigix el registre formal (complement del nom, subjecte, complement de règim), a triar *se* davant de [s] i a reconéixer els usos lexicalitzats d'*en* i *hi*.", "blocks": [{"title": "*En* partitiu: complement directe i subjecte", "text": "***En*** substituïx un nom **sense determinant** o acompanyat d'un **quantificador** (*tres*, *molt*, *poc*, *més*...). El quantificador es queda en la frase. Funciona igual si el nom és **complement directe** o **subjecte posposat** de verbs com *arribar*, *vindre*, *quedar* o *haver-hi*. Si el nom és **definit**, en canvi, s'usen *el*, *la*, *els*, *les*.", "examples": ["—Han arribat ja els convidats? —Només **n'**han arribat dos.", "—Hi havia molta gent? —**N'**hi havia moltíssima.", "—Has comprat pa? —No **n'**he comprat. / —Has comprat el pa? —Sí, ja **l'**he comprat."]}, {"title": "*En* complement del nom i de l'adjectiu", "text": "***En*** també representa un complement amb ***de*** que depén d'un **nom** (sobretot quan indica la part d'un conjunt) o d'un **adjectiu** que fa d'atribut. És un recurs propi del registre formal que evita repetir el complement.", "table": {"head": ["sense pronom", "amb pronom"], "rows": [["Vicent consulta la taula *de preus*.", "Vicent **en** consulta la taula."], ["Vam visitar una part *del museu*.", "**En** vam visitar una part."], ["Està molt content *de l'ordinador*.", "**N'**està molt content."]]}}, {"title": "Complement de règim: *en* o *hi*", "text": "El **complement de règim** és el complement amb preposició que exigix el verb. Si la preposició és ***de***, el pronom és ***en***; si és qualsevol altra (*a*, *en*, *amb*...), el pronom és ***hi***. Per a coses, en registre formal, es preferixen *en* i *hi* al pronom fort (*d'ell*, *en elles*).", "examples": ["Parlen de literatura → **En** parlen.", "No me'n vaig recordar (de telefonar-li).", "Va renunciar a la plaça → **Hi** va renunciar.", "Ha pensat en la proposta → **Hi** ha pensat."], "watch": [{"wrong": "Han promés inversions i tots confien en elles.", "right": "Han promés inversions i tots hi confien."}]}, {"title": "*En* i *hi* necessaris", "text": "Hi ha contextos en què el pronom és **obligatori**: un **quantificador sense nom** necessita *en*, i el verb existencial és sempre ***haver-hi***. Quan el nom s'avança o es reprén (**dislocació**), cal el pronom i, si és *en*, la preposició ***de***.", "examples": ["**En** vol més. / **En** tinc tres.", "No **hi** havia ningú. **Hi** ha moltes possibilitats.", "D'arròs, no **en** vull més. / No **en** vull més, d'arròs."], "watch": [{"wrong": "No havia ningú a la sala.", "right": "No hi havia ningú a la sala."}, {"wrong": "—Quants germans tens? —Tinc tres.", "right": "—Quants germans tens? —En tinc tres."}]}, {"title": "*Se* davant de [s]", "text": "El pronom reflexiu pren normalment la forma reforçada ***es*** davant de consonant (*es pentina*). Però davant d'un verb que comença pel **so [s]** se sol usar la forma plena ***se***, per a evitar que les dos *s* s'assimilen. Davant de vocal, la forma és elidida: *s'*.", "examples": ["L'acte **se** celebrarà demà.", "No **se** sap res encara.", "La reunió **se** suspendrà.", "L'exposició **s'**inaugurarà dijous."]}, {"title": "Usos lexicalitzats", "text": "En alguns verbs, ***en*** i ***hi*** ja no representen cap complement: formen part del verb. *En* apareix en verbs de **desplaçament** (*anar-se'n*, *vindre-se'n*, *pujar-se'n*, *eixir-se'n*); *hi*, en *haver-hi*, *veure-s'hi*, *trobar-s'hi* i frases fetes com *no s'hi val*.", "examples": ["**Me'n** vaig a casa. **Vine-te'n** al teatre.", "La xiqueta ja **se n'**ha pujat a casa.", "Sense ulleres no **m'hi** veig.", "Amb este vestit no **m'hi** trobe. Això no **s'hi** val!"]}], "remember": ["*En* substituïx noms indefinits o quantificats, tant si són complement directe com subjecte posposat: *només n'han arribat dos*.", "*En* també representa complements amb *de* d'un nom o d'un adjectiu: *en consulta la taula*, *n'està content*.", "Complement de règim: amb *de* → *en*; amb altres preposicions → *hi*.", "Un quantificador sense nom exigix *en* (*en vol més*), i *haver-hi* sempre porta *hi*.", "Davant de [s], forma plena *se*: *se celebra*, *se sap*.", "*Anar-se'n*, *vindre-se'n*, *veure-s'hi* i *trobar-s'hi* porten el pronom lexicalitzat."], "sources": [{"gram": "GVB", "section": "26.3.2", "title": "Formes plenes, reforçades, reduïdes i elidides", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=26_3_2"}, {"gram": "GVB", "section": "27.4.1", "title": "El pronom ne", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_4_1"}, {"gram": "GVB", "section": "27.4.2", "title": "El pronom hi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_4_2"}, {"gram": "GVB", "section": "27.5", "title": "Dislocacions amb pronom feble", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_5"}, {"gram": "GNV", "section": "21.3.4", "title": "Els pronoms de tercera persona referits a coses", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=21_3_4"}, {"gram": "GNV", "section": "22.3.2", "title": "Formes plenes, reforçades, reduïdes i elidides", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=22_3_2"}, {"gram": "GNV", "section": "23.4.1", "title": "El pronom ne", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_4_1"}, {"gram": "GNV", "section": "23.4.2", "title": "El pronom hi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_4_2"}, {"gram": "GNV", "section": "26.3.3.1", "title": "Les elisions i la pronominalització del nucli nominal", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_3_3_1"}, {"gram": "GNV", "section": "26.3.3.2", "title": "Les dislocacions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_3_3_2"}]}},
  {"type": "c1_mor_combinacions", "lesson": {"intro": "Aprendràs a combinar pronoms febles segons el registre, a distingir les duplicacions acceptables de les redundants i a fer concordar el participi amb els acusatius de tercera persona.", "blocks": [{"title": "L'orde i la forma en la combinació", "text": "L'orde dels pronoms és **fix**: ***se*** primer, després 2a i 1a persona, el **datiu** (*li*, *els*), l'**acusatiu** i, al final, ***en*** / ***hi*** / ***ho***. *Em*, *et*, *es* prenen la **forma plena** en primer lloc (*me la*), però s'elidixen davant de *ho* i *hi* (*m'ho*). Si el primer acaba en *-s*, el segon va en **forma reforçada** (*els els*, *els en*).", "examples": ["**Se m'**ha fet tard. **Se li** ha trencat el got.", "**Me la** van regalar. Quan **m'ho** diràs?", "Vam tornar-**los-els**. No **els en** vull dir res."]}, {"title": "Datiu + acusatiu o neutre", "text": "Amb el datiu de tercera persona, l'estàndard valencià general fa ***li*** + acusatiu (*li'l*, *li la*, *li l'*) i ***li ho*** amb el neutre. En els parlars septentrionals, *li* es convertix en *hi* i es posposa: ***l'hi***, ***la hi***. **No** és acceptable *se* com a datiu (interferència del castellà *se lo*). Si el complement és una oració o *això*, el pronom és *ho*.", "table": {"head": ["correcte", "incorrecte"], "rows": [["**Li ho** vaig dir (que no vindria).", "*Li'l* vaig dir. *Se'l* vaig dir."], ["**Li l'**he donat. / **L'hi** he donat.", "*Se l'*he donat."], ["**Els ho** vaig explicar.", "*Los ho* vaig explicar."]]}}, {"title": "Formal enfront de col·loquial", "text": "Algunes combinacions són habituals en la parla però **no** són adequades en **registres formals**: posposar *se* (*me s'*, *li s'*) i convertir *nos* i *vos* en *se* davant d'*en*. La *e* de suport que alguns parlars pronuncien (*els [e] la portaré*) tampoc s'escriu.", "watch": [{"wrong": "Me s'ha fet tard. Li s'ha perdut.", "right": "Se m'ha fet tard. Se li ha perdut."}, {"wrong": "Se n'anirem demà. Aneu-se'n!", "right": "Ens n'anirem demà. Aneu-vos-en!"}, {"wrong": "Els e la portaré demà.", "right": "Els la portaré demà."}]}, {"title": "Duplicacions acceptables", "text": "La duplicació és **correcta** quan un pronom **fort** fa de complement directe o indirecte: ha d'anar amb *a* i **amb** el pronom feble, i aporta un valor **contrastiu**. També és correcta en les **dislocacions**: el complement avançat o représ amb coma exigix un pronom de represa (i *de*, si el pronom és *en*).", "examples": ["**Li** ho vaig dir **a ell**, no a la seua germana.", "**M'**han avisat **a mi**.", "**Al teu germà**, no **li** digues res.", "**De pa**, **n'**hi ha poc. / Ja **en** tinc prou, **de vi**."]}, {"title": "Duplicacions redundants", "text": "Són **pleonasmes** no admesos en registre formal el pronom *en* quan el nom ja és al seu lloc, sense dislocar, i el ***li*** que repetix un complement indirecte posposat o un relatiu o interrogatiu (*a qui*).", "watch": [{"wrong": "N'hi ha poc de pa.", "right": "Hi ha poc pa. / De pa, n'hi ha poc."}, {"wrong": "Li hem regalat una bicicleta al xiquet.", "right": "Hem regalat una bicicleta al xiquet."}, {"wrong": "A qui li has de dir que t'ajude?", "right": "A qui has de dir que t'ajude?"}]}, {"title": "Concordança del participi", "text": "El participi dels temps compostos **sol concordar** en gènere i nombre amb els acusatius de tercera persona ***lo***, ***la***, ***los***, ***les***, sobretot en **femení**. La concordança es manté si darrere hi ha un **infinitiu**. **No** es fa amb el datiu *li*.", "examples": ["Encara no **l'**he **vista** (la germana).", "No me **les** he **menjades**, les taronges.", "No **les** he **sentides** entrar. No me **les** he **pogudes** comprar.", "La veritat, li **l'**he **dita**. / A Maria, **li** he **escrit**."]}], "remember": ["Orde fix: *se* + 2a/1a persona + datiu + acusatiu + *en*/*hi*/*ho*: *se li*, *se m'*, *li ho*.", "Per a una oració o *això*, *ho*: *li ho vaig dir*, *ja m'ho han dit*.", "*Se* no és mai datiu: *li l'he donat* (o *l'hi he donat*), no *se l'he donat*.", "Formal: *ens n'anirem*, *se m'ha fet tard*; no *se n'anirem*, *me s'ha fet tard*.", "Pronom fort de complement + feble és correcte (*li ho vaig dir a ell*); *n'hi ha poc de pa*, no.", "Participi concordat amb *la*, *les*... (*les he vistes*), no amb *li*."], "sources": [{"gram": "GVB", "section": "25.1", "title": "Introducció", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=25_1"}, {"gram": "GVB", "section": "26.4.1", "title": "L'orde dels pronoms febles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=26_4_1"}, {"gram": "GVB", "section": "26.4.2", "title": "La forma dels pronoms febles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=26_4_2"}, {"gram": "GVB", "section": "27.2.2", "title": "Els pronoms no reflexius de tercera persona", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_2_2"}, {"gram": "GVB", "section": "27.5", "title": "Dislocacions amb pronom feble", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_5"}, {"gram": "GNV", "section": "8.7", "title": "L'estructura informativa", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=8_7"}, {"gram": "GNV", "section": "21.1", "title": "Caracterització general: els pronoms forts i els febles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=21_1"}, {"gram": "GNV", "section": "22.4.1", "title": "L'orde dels pronoms febles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=22_4_1"}, {"gram": "GNV", "section": "22.4.2", "title": "La forma dels pronoms febles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=22_4_2"}, {"gram": "GNV", "section": "23.2.2", "title": "Els pronoms no reflexius de tercera persona", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_2_2"}, {"gram": "GNV", "section": "26.3.3.2", "title": "Les dislocacions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_3_3_2"}]}},
  {"type": "c1_mor_relatius", "lesson": {"intro": "Aprendràs a triar el relatiu adequat en registre formal, a construir el relatiu possessiu i els relatius neutres, a usar bé article + *que* i a evitar les construccions analítiques i els pleonasmes.", "blocks": [{"title": "Quin relatiu segons el context", "text": "La tria depén de si la relativa és **especificativa** o **explicativa** i de si hi ha **preposició**. Sense preposició, ***que***; en explicatives també ***el qual***, però **mai** *qui*. Amb preposició àtona (*a*, *de*, *en*, *amb*, *per*): ***què*** (coses), ***qui*** (persones) o ***el qual***. Amb preposició **tònica** o composta, només *el qual*.", "table": {"head": ["context", "relatiu"], "rows": [["especificativa, sense preposició", "*que* (no *el qual*)"], ["explicativa, sense preposició", "*que* / *el qual* (no *qui*)"], ["preposició àtona", "*què*, *qui*, *el qual*"], ["preposició tònica (*contra*, *segons*...)", "*el qual*"]]}, "examples": ["Va gratificar el client **que** havia tacat.", "És una malaltia **contra la qual** no podem lluitar."]}, {"title": "*On*, *quan* i *com*", "text": "***On*** indica lloc i admet altres preposicions (*des d'on*, *per on*). Si el lloc és **metafòric**, es preferix *en què* o *en el qual*. ***Quan*** s'usa **sense antecedent**; amb antecedent, *que*, *en què* o *en el qual*. ***Com*** amb antecedent només va darrere de *manera* o *forma*.", "examples": ["Este és el lloc **des d'on** ha de començar la carrera.", "Hi ha llengües **en què** el subjecte va al final.", "Això va passar l'any **en què** va faltar el pare.", "De la manera **com** t'ha contestat, ja ho sap."], "watch": [{"wrong": "L'any quan va faltar el pare.", "right": "L'any que (en què) va faltar el pare."}]}, {"title": "El relatiu possessiu", "text": "La possessió s'expressa amb ***del qual*** (*de la qual*, *dels quals*, *de les quals*) **darrere** del nom posseït. Concorda amb el **posseïdor**, que és l'antecedent, i no amb la cosa posseïda. És una construcció pròpia dels registres formals.", "examples": ["És una dona tots els fills **de la qual** són educats.", "He anat a uns bancs, els caixers **dels quals** no funcionen.", "Parla amb Jaume, la paciència **del qual** és notòria."], "watch": [{"wrong": "Tinc un amic que el seu pare és obrer.", "right": "Tinc un amic el pare del qual és obrer."}]}, {"title": "Relatius neutres i antecedent repetit", "text": "Per a reprendre **tota una oració** s'usa ***la qual cosa*** o ***cosa que***, mai *lo qual* ni *lo que*. En les explicatives també es pot **repetir l'antecedent** o un sinònim: davant de *que* (*quantitat que*) o darrere d'*el qual* (*la qual suma*).", "examples": ["Va callar, **la qual cosa** és molt significativa.", "Férem un gran esforç, **cosa que** ens permet anar més relaxats.", "Va costar trenta mil euros, **quantitat que** pagarà la Diputació."], "watch": [{"wrong": "Va callar, lo qual és significatiu.", "right": "Va callar, la qual cosa és significativa."}]}, {"title": "Article + *que*", "text": "***El que***, *la que*, *els que* i *les que* només s'usen **sense antecedent** (*el que* neutre = 'allò que') o quan el nom s'ha **elidit** perquè ja ha aparegut. Sense antecedent, per a persones, ***qui*** o ***el qui*** (més formal), i també *el que*.", "examples": ["Fes **el que** consideres convenient.", "Anirem en el meu cotxe i en **el que** portarà Lluïsa.", "**El qui** ho sàpia, que ho diga."], "watch": [{"wrong": "La ciutat en la que visc.", "right": "La ciutat en què (en la qual, on) visc."}]}, {"title": "Construccions analítiques i pleonasmes", "text": "En la llengua col·loquial, *que* fa de simple nexe i un **pronom feble** o un **possessiu** fa la funció del relatiu. En registre formal cal la construcció **sintètica**, sense pronoms redundants. Atenció: en *on hi ha*, *hi* forma part d'***haver-hi*** i és correcte.", "table": {"head": ["formal", "no formal"], "rows": [["És un home **a qui** no lluïx la faena.", "És un home *que li* (*a qui li*) lluïx..."], ["És un tema **que** no domine.", "És un tema *que no el* domine."], ["El poble **on** vaig nàixer.", "El poble *on hi* vaig nàixer."], ["És un poble **on hi ha** molta gent.", "És un poble *que hi ha* molta gent."]]}}], "remember": ["Especificativa sense preposició: *que*; explicativa: *que* o *el qual*, mai *qui*.", "Preposició tònica: *el qual* (*contra la qual*); *què* i *qui* només amb *a*, *de*, *en*, *amb* i *per*.", "Possessiu: *el pare del qual*, concordat amb el posseïdor.", "*La qual cosa* o *cosa que* per a reprendre una oració; mai *lo qual*.", "Article + *que* només sense antecedent o amb el nom elidit.", "Res de pronoms redundants: *a qui lluïx*, *on vaig nàixer*; però *on hi ha* és correcte."], "sources": [{"gram": "GVB", "section": "19.5.2", "title": "Altres usos", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=19_5_2"}, {"gram": "GVB", "section": "28.2", "title": "Les oracions relatives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=28_2"}, {"gram": "GVB", "section": "28.3.1", "title": "Que", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=28_3_1"}, {"gram": "GVB", "section": "28.3.3", "title": "Qual", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=28_3_3"}, {"gram": "GVB", "section": "28.3.4", "title": "Qui", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=28_3_4"}, {"gram": "GVB", "section": "28.4.1", "title": "Quan", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=28_4_1"}, {"gram": "GVB", "section": "28.4.2", "title": "On", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=28_4_2"}, {"gram": "GVB", "section": "28.4.3", "title": "Com", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=28_4_3"}, {"gram": "GNV", "section": "24.2", "title": "Formes i usos dels relatius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=24_2"}, {"gram": "GNV", "section": "24.3.1", "title": "Relatives explicatives amb antecedent repetit", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=24_3_1"}, {"gram": "GNV", "section": "24.3.2", "title": "Els relatius que, qui, què i article + qual", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=24_3_2"}, {"gram": "GNV", "section": "24.3.3", "title": "Els relatius adverbials", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=24_3_3"}, {"gram": "GNV", "section": "24.3.4", "title": "Les construccions de relatiu analítiques", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=24_3_4"}]}},
  {"type": "c1_mor_exclamatius", "lesson": {"intro": "Aprendràs a triar l'exclamatiu adequat (*quin*, *quant*, *que*, *com*, *qui*), a construir *quin* + substantiu + *més* + adjectiu i a substituir el *lo* intensiu per construccions genuïnes.", "blocks": [{"title": "Variables i invariables", "text": "Els exclamatius **variables** són ***quin*** i ***quant***: modifiquen un **substantiu** i concorden amb ell. Els **invariables** són ***que*** (davant d'**adjectiu** o **adverbi**), ***com*** (modifica el **verb**) i ***qui*** en expressions com *qui ho diria!*", "table": {"head": ["exclamatiu", "modifica", "exemple"], "rows": [["*quin*, *quina*...", "substantiu (qualitat)", "Quina xica més simpàtica!"], ["*quant*, *quanta*...", "substantiu (quantitat)", "Quanta gent!"], ["*que*", "adjectiu o adverbi", "Que bé que parla!"], ["*com*", "verb", "Com plou!"]]}}, {"title": "*Quin* + substantiu + *més* + adjectiu", "text": "***Quin*** és **qualitatiu**: atribuïx al substantiu una propietat en grau molt alt. La propietat pot quedar implícita (*Quina xica!*) o explicitar-se amb un **adjectiu precedit de *més***. **No** es pot usar *que* davant de substantiu.", "examples": ["**Quina** pel·lícula **més** bonica!", "**Quin** home **més** desastrat!", "**Quina** calor **més** apegalosa!"], "watch": [{"wrong": "Que fred que fa!", "right": "Quin fred que fa!"}, {"wrong": "Que calor més apegalosa!", "right": "Quina calor més apegalosa!"}]}, {"title": "*Quant*: quantitat", "text": "***Quant*** pondera la **quantitat** i concorda amb el nom (*quanta*, *quants*, *quantes*). Davant d'un nom **masculí singular** va seguit de ***de***. Amb valor **adverbial** queda invariable i pondera l'acció del verb.", "examples": ["**Quanta** misèria que hi ha!", "**Quant de** sucre t'has posat!", "**Quantes** coses que no podrem aprofitar!", "**Quant** que saps!"]}, {"title": "*Que* i *com*", "text": "***Que*** (sense accent) intensifica un **adjectiu** o un **adverbi**. ***Com*** modifica el verb i indica quantitat ('molt') o manera; si s'explicita l'adjectiu o l'adverbi, va introduït per ***de***. Com que l'exclamatiu va al principi, el **subjecte es posposa** al final.", "examples": ["**Que** pesat que és el teu amic!", "**Com** la vull! **Com** s'ha posat per no res!", "**Com** està **d'**alta la xiqueta!", "Que bé que parla **ta mare**!"]}, {"title": "El *que* de les exclamatives", "text": "Després del sintagma exclamatiu apareix normalment un ***que*** **àton** (una conjunció) que l'enllaça amb la resta de l'oració. És potestatiu: es pot ometre. No porta mai accent, igual que l'exclamatiu *que*. Altres exclamatives elidixen l'exclamatiu o comencen per ***si***.", "examples": ["Que valent **que** és!", "Quina barbaritat (**que**) acabes de dir!", "(Quina) llàstima que no vinga!", "**Si** està plovent!"]}, {"title": "Sense *lo* intensiu", "text": "L'article neutre ***lo*** **no** és acceptable amb el valor intensiu que tenen *que* o *com* en les exclamatives, encara que siga freqüent en la parla. Cal substituir-lo per construccions genuïnes amb ***tan... que***, ***com*** + verb + ***de*** o ***que***.", "watch": [{"wrong": "Amb lo bonic que és, i no para de plorar!", "right": "Tan bonic que (o com) és, i no para de plorar!"}, {"wrong": "No saps lo bé que treballen.", "right": "No saps com treballen de bé."}]}], "remember": ["*Quin* i *quant* van amb substantius; *que*, amb adjectius i adverbis; *com*, amb verbs.", "Quin + substantiu + *més* + adjectiu: *quina xica més simpàtica!*", "Mai *que* davant de nom: *quin fred!*, *quina calor!*", "*Quant de* davant de masculí singular: *quant de temps!*", "El *que* àton després de l'exclamatiu és opcional: *que valent (que) és!*", "Res de *lo* intensiu: *com treballen de bé*, *tan bonic que és*."], "sources": [{"gram": "GVB", "section": "19.5.2", "title": "Altres usos", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=19_5_2"}, {"gram": "GVB", "section": "29.4", "title": "Quin", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=29_4"}, {"gram": "GVB", "section": "29.5", "title": "Quant", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=29_5"}, {"gram": "GVB", "section": "29.7", "title": "Formes i usos dels exclamatius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=29_7"}, {"gram": "GNV", "section": "7.4.2", "title": "Els signes d'exclamació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=7_4_2"}, {"gram": "GNV", "section": "25.4", "title": "Els exclamatius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=25_4"}]}},
  {"type": "c1_mor_quantificadors", "lesson": {"intro": "Aprendràs a triar entre *u* i *un*, a llegir les xifres romanes, a usar els multiplicatius i els col·lectius, a precisar indefinits com *qualsevol*, *cadascú* o *hom*, i a quantificar amb locucions com *pel cap alt* o *si més no*.", "blocks": [{"title": "Cardinals: *u* o *un*, lletra o xifra", "text": "S'usa ***un*** (*una*) quan el numeral **modifica un nom**, explícit o implícit. S'usa ***u*** quan fa d'**ordinal** (*la pàgina u*, *l'u de gener*), quan és el **nom del número** o quan no modifica cap nom (*van dos a u*). Usats com a ordinals, els cardinals van en **masculí**: *la pàgina tres-cents*. Dins d'un text, se solen escriure amb **lletra del zero al nou** i amb **xifres a partir del 10**.", "table": {"head": ["context", "forma", "exemple"], "rows": [["modifica un nom", "*un*, *una*", "*Dona-me'n un.* / *vint-i-una persones*"], ["valor d'ordinal", "*u*", "*el capítol vint-i-u*, *l'u de maig*"], ["nom del número", "*u*", "*u, dos, tres...* / *van dos a u*"], ["ordinal amb nom femení", "masculí", "*la pregunta vint-i-dos*"]]}, "watch": [{"wrong": "la pàgina tres-centes", "right": "la pàgina tres-cents"}]}, {"title": "Xifres romanes", "text": "Les xifres romanes es lligen com a **ordinals**: *Jaume II* (*segon*), *les III Jornades* (*terceres*). Però quan es **posposen a un nom propi** i són **superiors a deu**, es lligen com a **cardinals**: *Joan XXIII* (*vint-i-tres*), *Alfons XII* (*dotze*).", "examples": ["**Carles V** → Carles *cinqué*", "**Benet XVI** → Benet *setze*", "**Lluís XIV** → Lluís *catorze*"], "watch": [{"wrong": "Joan vint-i-tresé", "right": "Joan vint-i-tres"}]}, {"title": "Multiplicatius i col·lectius", "text": "Els multiplicatius (*doble*, *triple*, *quàdruple*...) **varien** quan valen 'tantes voltes una xifra' (*quíntuple* o *quíntupla*), però són **invariables** quan indiquen els elements que formen una entitat (*la triple aliança*). ***Doble*** no varia mai. En la parla es preferix ***tantes voltes més***. Els col·lectius són substantius: *parell*, *dotzena*, *vintena*, *centenar*, *miler*.", "table": {"head": ["valor", "forma", "exemple"], "rows": [["2", "*parell*", "*un parell de pantalons*"], ["12", "*dotzena*", "*una dotzena d'ous*"], ["100", "*centena*, *centenar*", "*un centenar de socis*"], ["1.000", "*miler*, *milenar*", "*un miler de manifestants*"], ["×4", "*quàdruple*", "*quatre voltes més alt*"]]}}, {"title": "Indefinits: *qualsevol*, *cadascú*, *hom*, *la resta*", "text": "***Qualsevol*** fa el plural ***qualssevol*** i, posposat, concorda: *tres bolígrafs qualssevol*. Els **pronoms** genèrics, sense antecedent, acaben en *-u*: *u*, *algú*, ***cada u***, ***cadascú***; si hi ha antecedent, s'usa el quantificador amb *-n*: *cadascun (d'ells)*. ***Hom*** és arcaic i molt formal: preferix *es pensava* o *hi ha qui opina*. Per a 'el que queda', ***la resta***, no *lo demés*.", "examples": ["**Cadascú** va dir la seua opinió.", "Parlaren tres candidats i **cadascun** va dir la seua.", "Abans **es pensava** (*hom pensava*) que la Terra era plana."], "watch": [{"wrong": "Tres bolígrafs qualsevol", "right": "Tres bolígrafs qualssevol"}]}, {"title": "Quantitatius invariables i *de*", "text": "***Massa***, ***força***, ***prou***, ***més***, ***menys*** (o ***manco***) i ***gens*** no varien mai. ***Gens*** porta sempre *de*; ***prou*** només davant de **masculí singular** (*prou de pa*, però *prou farina*); ***massa***, *més* i *menys*, mai. Amb valor d'inferioritat també s'usa ***més poc***. El pronom ***res*** pren *de* davant d'adjectiu: *res de transcendent*. I recorda la construcció *no tenen **res a fer***.", "examples": ["No té **gens de** vergonya.", "Ens queda **prou** farina.", "Això no té **res de** nou.", "Ara treballem **més poc** que abans."], "watch": [{"wrong": "Hi havia massa de gent.", "right": "Hi havia massa gent."}]}, {"title": "Locucions de quantitat", "text": "Per a la **comparació proporcional**, ***com més... més*** (o *menys*). Per al **límit màxim**: *com a màxim*, *com a molt*, *a tot estirar*, *pel cap alt*. Per al **límit mínim**: *com a mínim*, *almenys*, *si més no*, *pel cap baix*.", "table": {"head": ["valor", "locucions", "exemple"], "rows": [["proporció", "*com més... més*", "*Com més corres, més et canses.*"], ["màxim", "*com a màxim*, *a tot estirar*, *pel cap alt*", "*Tardarà, a tot estirar, una hora.*"], ["mínim", "*com a mínim*, *si més no*, *pel cap baix*", "*Hi havia, pel cap baix, cent persones.*"]]}, "watch": [{"wrong": "Mentre més estudies, més saps.", "right": "Com més estudies, més saps."}]}], "remember": ["*Un* modifica un nom; *u* fa d'ordinal o de nom del número: *el capítol vint-i-u*.", "Xifra romana posposada a un nom propi i superior a deu: cardinal (*Joan XXIII*, 'vint-i-tres').", "*Doble* no varia; *la triple aliança*, invariable; *quíntuple* o *quíntupla* si val 'cinc voltes'.", "*Cadascú* i *cada u* sense antecedent; *cadascun* amb antecedent. Plural: *qualssevol*.", "*Pel cap alt* = com a màxim; *pel cap baix* i *si més no* = com a mínim; *com més... més*.", "*Res de* + adjectiu (*res de bo*) i *res a* + infinitiu (*no tenen res a fer*)."], "sources": [{"gram": "GVB", "section": "22.2.3", "title": "Acotacions a l'ús de les formes un/u", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=22_2_3"}, {"gram": "GVB", "section": "22.2.4", "title": "Variacions de gènere i nombre", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=22_2_4"}, {"gram": "GVB", "section": "22.3.2", "title": "Aspectes formals i sintàctics", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=22_3_2"}, {"gram": "GVB", "section": "22.5", "title": "Els numerals multiplicatius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=22_5"}, {"gram": "GVB", "section": "22.6", "title": "Els numerals col·lectius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=22_6"}, {"gram": "GVB", "section": "23.3", "title": "Aspectes formals i sintàctics", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=23_3"}, {"gram": "GVB", "section": "24.2.6", "title": "Qualsevol", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=24_2_6"}, {"gram": "GVB", "section": "24.3.1", "title": "U, algú, cadascú i cada u", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=24_3_1"}, {"gram": "GVB", "section": "24.3.5", "title": "Hom", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=24_3_5"}, {"gram": "GVB", "section": "24.3.6", "title": "Res", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=24_3_6"}, {"gram": "GVB", "section": "37.4.1", "title": "Almenys", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=37_4_1"}, {"gram": "GNV", "section": "18.4.2", "title": "Aspectes formals i sintàctics", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=18_4_2"}, {"gram": "GNV", "section": "19.3", "title": "Els pronoms indefinits", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=19_3"}, {"gram": "GNV", "section": "20.2", "title": "Aspectes formals i sintàctics", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=20_2"}]}},
  {"type": "c1_mor_preposicions", "lesson": {"intro": "Aprendràs a distingir les preposicions àtones de les tòniques, a usar bé les compostes (*cap a*, *fins a*, *com a*, *per a*), a triar entre *al* i *en* + infinitiu i a aplicar la caiguda i el canvi de les preposicions àtones.", "blocks": [{"title": "Àtones, tòniques i compostes", "text": "Són **àtones** *a*, *en*, *de*, *amb* i *per*, i també les **compostes** *des de*, *fins a*, *cap a*, *per a* i *com a*. Totes les altres simples són **tòniques** (*sense*, *entre*, *contra*, *sobre*, *segons*). Les **locucions** fan la mateixa funció: *a causa de*, *a fi de*, *a força de*, *arran de*, *en compte de*, *a mitjan* (sense determinant).", "table": {"head": ["classe", "formes"], "rows": [["àtones simples", "*a*, *en*, *de*, *amb*, *per*"], ["compostes", "*des de*, *fins a*, *cap a*, *per a*, *com a*"], ["tòniques", "*sense*, *entre*, *contra*, *sobre*, *sota*, *segons*..."], ["locucions", "*a fi de*, *a força de*, *arran de*, *en compte de*, *a mitjan*"]]}, "watch": [{"wrong": "a mitjans de desembre", "right": "a mitjan desembre"}, {"wrong": "Vam sopar en els pares.", "right": "Vam sopar amb els pares."}]}, {"title": "*Cap a*, *fins a* i *com a*", "text": "***Cap a*** es reduïx a *cap* davant d'*ací*, *allí*, *amunt*, *avall*... i d'*aquest*, *aqueix*, *aquell*. ***Fins a*** es reduïx a *fins* davant d'adverbis díctics (*demà*, *ara*) i de *que* o *fa*, però es manté amb hores, dates i usos no temporals (*fins a sis persones*). ***Com a*** val 'en qualitat de' i es reduïx a *com* quan el terme porta **determinant**.", "table": {"head": ["forma plena", "forma reduïda"], "rows": [["*cap a la mar*, *cap a eixe carrer*", "*cap allí*, *cap amunt*, *cap aquell carrer*"], ["*fins a les onze*, *fins a localitzar-los*", "*fins demà*, *fins que vinga*, *fins fa poc*"], ["*com a president*, *com a llops*", "*com un llop*, *com el puny*"]]}}, {"title": "*Al* o *en* + infinitiu", "text": "Les dos construccions equivalen a *quan*. ***Al*** + infinitiu és **duratiu**: l'acció principal passa *mentre* dura la de l'infinitiu. ***En*** + infinitiu és **puntual**: indica **anterioritat immediata**. No són adequades amb un valor **només causal**: cal una causal amb *com que*.", "examples": ["**Al** passar per la plaça ens va saludar. ('mentre passava')", "**En** arribar el pare, avisa'm. ('tot seguit que arribe')", "**En** fer-se de dia anirem a l'hort."], "watch": [{"wrong": "Al ser tan tard, se n'anaren.", "right": "Com que era tan tard, se n'anaren."}]}, {"title": "*Per* i *per a* davant d'infinitiu", "text": "***Per*** + infinitiu indica **causa** (*multa per haver corregut*), **mancança** (*pisos per vendre*) i finalitat amb la intenció de **no** fer una cosa (*no menja per no embrutar*). Amb subjecte agentiu i intenció, la llengua literària usa *per*, però també s'accepta *per a*. ***Per a*** és obligatori en les finals **sense intencionalitat**: subjecte inanimat o infinitiu que depén d'un nom, adjectiu o quantitatiu.", "examples": ["Esta caixa servirà **per a** guardar revistes.", "No tinc prou informació **per a** decidir-me.", "Treballe **per** (o **per a**) guanyar-me la vida."]}, {"title": "Usos de *a*, *de*, *en* i *amb*", "text": "***A***: destinació, topònims, hores, distribució (*tres vegades a la setmana*), manera (*a la brasa*). ***En***: durades (*en un moment*) i davant d'indefinits, demostratius i noms sense determinant. ***De***: manera (*de valent*), temps (*de menuts*) i dislocacions a la dreta (*no en vull, de pa*), on és **obligatòria**. ***Amb***: instrument, companyia, manera.", "examples": ["Ho trobaràs **en** algun calaix.", "Passege mitja hora **al** dia.", "No n'he comprat, **de** pa.", "Fa les coses **amb** molta calma."]}, {"title": "Caiguda i canvi de preposicions", "text": "*A*, *de*, *en* i *amb* **cauen davant de la conjunció *que***: en complements de règim, darrere de noms (*por que*), d'*abans*, *després*, *des*, *fins* i de locucions (*en cas que*). Si la frase queda forçada, usa un **infinitiu** o *el fet que*. Alguns verbs **canvien** la preposició davant d'infinitiu: *tardar a*, *afanyar-se a*, *amenaçar de*, *ser el primer a*.", "table": {"head": ["amb nom", "davant de *que* / infinitiu"], "rows": [["*Gràcies a ell*", "*Gràcies que m'ho has dit*"], ["*L'amenaçà amb l'expulsió*", "*L'amenaçà que l'expulsaria* / *M'amenaça de dir-ho*"], ["*Des d'este matí*", "*Des que ha arribat*"], ["*Tarda molt en les decisions*", "*Tarden molt a acabar*"]]}, "watch": [{"wrong": "Ves a per pa.", "right": "Ves a comprar pa."}]}], "remember": ["Àtones: *a*, *en*, *de*, *amb*, *per* i les compostes; la resta són tòniques.", "*Cap allí*, *fins demà*, *com un llop*; però *cap a la mar*, *fins a les onze*, *com a president*.", "*Al* + infinitiu = 'mentre'; *en* + infinitiu = 'tot seguit que'; mai amb valor només causal.", "*Per a* en les finals sense intenció: *serveix per a guardar*, *prou informació per a decidir*.", "Davant de *que* cauen *a*, *de*, *en*, *amb*: *des que*, *en cas que*, *gràcies que*."], "sources": [{"gram": "GNV", "section": "26.2", "title": "Les classes de preposicions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_2"}, {"gram": "GNV", "section": "26.2.3", "title": "Les preposicions simples i les compostes", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_2_3"}, {"gram": "GNV", "section": "26.3.1.3", "title": "La construcció «en o al + infinitiu»", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_3_1_3"}, {"gram": "GNV", "section": "26.3.3", "title": "La preposició de", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_3_3"}, {"gram": "GNV", "section": "26.3.4", "title": "Les preposicions per i per a", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_3_4"}, {"gram": "GNV", "section": "26.3.5", "title": "L'elisió i el canvi de preposicions àtones", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_3_5"}, {"gram": "GNV", "section": "26.4.1", "title": "La preposició cap a", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_4_1"}, {"gram": "GNV", "section": "26.4.2", "title": "Les preposicions des de i fins a", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_4_2"}, {"gram": "GNV", "section": "26.4.3", "title": "La preposició com a", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_4_3"}, {"gram": "GVB", "section": "30.3", "title": "A", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=30_3"}, {"gram": "GVB", "section": "32.13", "title": "A mitjan", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=32_13"}, {"gram": "GVB", "section": "32.26", "title": "En compte de", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=32_26"}, {"gram": "GVB", "section": "33.1", "title": "El canvi de preposicions àtones", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=33_1"}, {"gram": "GVB", "section": "33.3", "title": "La seqüència de preposicions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=33_3"}]}},
  {"type": "c1_mor_adverbis", "lesson": {"intro": "Aprendràs a expressar dubte amb *potser* o *pot ser que*, a usar bé les paraules negatives, a coordinar adverbis en *-ment* segons l'AVL i a distingir *baix*, *davall* i *sota*, *a soles* i *només* / *no més*.", "blocks": [{"title": "Dubte i probabilitat", "text": "Els adverbis modals de dubte són en *-ment* (*possiblement*, *probablement*, *segurament*), excepte ***potser***, que és una paraula composta. També hi ha *tal vegada*, *tal volta* i *qui sap*. Amb tots ells, el mode tradicional és l'**indicatiu**: el subjuntiu és una innovació que convé **evitar en registre formal**. En canvi, ***pot ser que*** (verb + verb) regix **subjuntiu**.", "table": {"head": ["forma", "mode", "exemple"], "rows": [["*potser*", "indicatiu", "*Potser vindrà demà.*"], ["*tal vegada*, *possiblement*", "indicatiu", "*Possiblement arribaran demà.*"], ["*pot ser que*", "subjuntiu", "*Pot ser que vinga demà.*"]]}, "watch": [{"wrong": "A lo millor ve demà.", "right": "Potser (o tal vegada) vindrà demà."}]}, {"title": "Afirmació i negació", "text": "Per a **afirmar**: *sí (que)*, *també*, *efectivament*, *en efecte*, *sens dubte*, *de veres*, *de veritat*. Per a **negar**: *no*, *tampoc*, *de cap manera*, *de ninguna manera*, *en absolut*, *no gens*. Recorda que *també no* és incorrecte: s'usa ***tampoc***.", "examples": ["—Vas ser tu? —**Efectivament**, vaig ser jo.", "—T'ha molestat? —**En absolut**.", "**Sens dubte**, és la millor proposta."]}, {"title": "Les paraules negatives", "text": "*Ningú*, *cap*, *res*, *gens*, *mai*, *enlloc* i *tampoc* **exigixen *no*** si van **darrere del verb**; si van **davant**, el *no* és **opcional**. En les respostes poden anar soles o amb *no*: *Res* / *No res*. En **preguntes i condicionals** tenen valor **positiu**.", "table": {"head": ["posició", "exemple"], "rows": [["darrere del verb", "*No l'ha convidat ningú.*"], ["davant del verb", "*Ningú (no) l'ha convidat.*"], ["resposta", "*—Què t'abellix? —Res.* / *—No res.*"], ["pregunta", "*Has anat mai a les Columbretes?* ('alguna vegada')"]]}, "watch": [{"wrong": "L'ha convidat ningú.", "right": "No l'ha convidat ningú."}]}, {"title": "Adverbis en *-ment* coordinats", "text": "L'adverbi es forma sobre el **femení** de l'adjectiu (*cortesa* → *cortesament*). Segons l'AVL, quan se'n coordinen dos o més, **es pot elidir *-ment* del segon** (i dels següents), però hui es **preferix mantindre'l en tots**.", "examples": ["Caminava **tranquil·lament i lentament**. (preferit)", "Caminava **tranquil·lament i lenta**. (acceptat)", "Va gestionar el departament **hàbilment i eficaçment**."]}, {"title": "*Baix*, *davall* i *sota*", "text": "***Davall*** indica la **part inferior** en vertical, amb contacte o sense: *davall de la taula*. ***Baix*** vol dir 'en la part baixa' i sol anar **sense complement** (*Ves-te'n baix*); amb complement només val 'en una part més baixa' (*baix del bancal*). ***Sota*** és formal i s'usa sobretot amb valors **figurats**: *sota pressió*, *sota jurament*, *sota zero*.", "table": {"head": ["forma", "ús", "exemple"], "rows": [["*davall (de)*", "part inferior", "*El gat dorm davall de la taula.*"], ["*baix*", "part baixa, sense complement", "*Espera'm baix.*"], ["*sota*", "submissió, valor figurat", "*Va firmar sota pressió.*"]]}, "watch": [{"wrong": "S'ha amagat baix del llit.", "right": "S'ha amagat davall del llit."}]}, {"title": "*Sols*, *a soles*, *només* i *no més*", "text": "***Només***, ***sols***, ***solament***, ***únicament*** i ***tan sols*** destaquen un element: 'no més que això'. ***A soles*** vol dir sobretot 'sense companyia' (*ell a soles* = 'ell sol'). No confongues ***només*** (en una paraula) amb ***no més***, que és la negació *no* + *més*.", "examples": ["**Només** tinc deu euros.", "Arribeu **no més** tard de les nou.", "El motor funciona **ell a soles**.", "Ni **tan sols** em va saludar."], "watch": [{"wrong": "No més tinc deu euros.", "right": "Només tinc deu euros."}]}], "remember": ["*Potser* (junt) + indicatiu en registre formal; *pot ser que* + subjuntiu.", "Paraula negativa darrere del verb: cal *no*. Davant: el *no* és opcional.", "*—Res.* o *—No res.*: les dos respostes són correctes.", "*-ment* coordinats: es pot elidir del segon, però és preferible mantindre'l en tots.", "*Davall de la taula*, *sota pressió*, *baix* sense complement.", "*Només* = únicament; *no més* = no + més (*no més tard de les nou*)."], "sources": [{"gram": "GVB", "section": "31.17", "title": "Sota", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=31_17"}, {"gram": "GVB", "section": "34.2", "title": "Adverbis derivats d'adjectius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=34_2"}, {"gram": "GVB", "section": "35.3.2", "title": "Davall", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=35_3_2"}, {"gram": "GVB", "section": "35.3.4", "title": "Baix", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=35_3_4"}, {"gram": "GVB", "section": "37.4.3", "title": "Només", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=37_4_3"}, {"gram": "GVB", "section": "38.1", "title": "Els adverbis modals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=38_1"}, {"gram": "GVB", "section": "38.2.4", "title": "Les paraules negatives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=38_2_4"}, {"gram": "GNV", "section": "27.3.2", "title": "Precisions sobre els adverbis de manera", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=27_3_2"}, {"gram": "GNV", "section": "27.4.2", "title": "Els adverbis preposicionals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=27_4_2"}, {"gram": "GNV", "section": "27.6", "title": "Els adverbis quantitatius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=27_6"}, {"gram": "GNV", "section": "27.7.1", "title": "Els adverbis modals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=27_7_1"}, {"gram": "GNV", "section": "27.7.2", "title": "Els adverbis d'afirmació i de negació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=27_7_2"}, {"gram": "GNV", "section": "28.5", "title": "Precisions sobre l'ús de l'indicatiu i el subjuntiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_5"}]}},
  {"type": "c1_mor_conjuncions", "lesson": {"intro": "Aprendràs a distingir *per què*, *perquè*, *per a què* i *el perquè*, a triar les causals i consecutives formals, a no confondre *sinó* i *si no* i a usar les locucions condicionals amb el mode adequat.", "blocks": [{"title": "*Per què*, *perquè*, *per a què*, *el perquè*", "text": "***Per què*** (separat i amb accent) és la preposició *per* + l'interrogatiu *què*: pregunta per la **causa**, en directa o en indirecta. També pot ser el **relatiu** *què* darrere de *per* (= *pel qual*). ***Perquè*** (junt) és la **conjunció** causal o final. ***Per a què*** pregunta per la **finalitat**. I amb article, ***el perquè*** és un substantiu: 'el motiu'.", "table": {"head": ["forma", "què és", "exemple"], "rows": [["*per què*", "interrogatiu de causa", "*Per què no has vingut?*"], ["*per què*", "relatiu (= pel qual)", "*Els motius per què ho he fet.*"], ["*perquè*", "conjunció causal o final", "*Perquè estava malalt.*"], ["*per a què*", "interrogatiu de finalitat", "*Per a què vols el martell?*"], ["*el perquè*", "substantiu (= el motiu)", "*No arribí a entendre el perquè.*"]]}}, {"title": "Causa o finalitat: el mode ho decidix", "text": "La conjunció ***perquè*** és **causal** amb indicatiu i **final** amb subjuntiu. En els registres formals, la conjunció final és *perquè*; la forma *per a que* és pròpia de la llengua col·loquial. Altres finals formals són ***a fi que*** i ***per tal que***. Recorda que davant de *que* **cau la preposició**: *a fi de* + infinitiu, però *a fi que* + oració.", "examples": ["Ha suspés **perquè no havia estudiat**. (causa)", "Aniré a parlar amb ell **perquè m'explique** què ha passat. (finalitat)", "Han analitzat l'aigua **a fi que** els veïns beguen tranquils."], "watch": [{"wrong": "Ho repetisc per a que ho entengues. (registre formal)", "right": "Ho repetisc perquè ho entengues."}, {"wrong": "Ho fem a fi de que estigues tranquil.", "right": "Ho fem a fi que estigues tranquil."}]}, {"title": "Causals formals i *doncs* consecutiu", "text": "A més de *perquè*, els registres cuidats disposen de ***ja que***, ***atés que***, ***vist que***, ***donat que***, *per tal com* i ***puix que***; *car* és molt formal i quasi només literari. En canvi, ***doncs*** és **consecutiu**: introduïx el que es deriva del que s'ha dit, com *de manera que* o *així que*. Per a expressar una causa, no l'uses: tria *perquè* o *ja que*.", "examples": ["—Dius que tens calor? —**Doncs** lleva't la jaqueta.", "**Atés que** ja ha arribat Ferran, podem començar.", "**Puix que** venen temps difícils, haurem de preparar-nos."], "watch": [{"wrong": "No vaig anar a la festa, doncs estava cansat.", "right": "No vaig anar a la festa, perquè (o ja que) estava cansat."}]}, {"title": "*Sinó*, *sinó que* i *si no*", "text": "***Sinó*** (junt) és **substitutiu**: afirma del segon element el que es nega del primer; davant d'una oració amb verb conjugat, ***sinó que***. També significa 'excepte' (*qui sinó tu?*). ***Si no*** (separat) és la condicional *si* + la negació *no*, i pot equivaler a 'en cas contrari'. Prova: si pots dir *en cas que no*, escriu-ho separat.", "table": {"head": ["forma", "valor", "exemple"], "rows": [["*sinó*", "substitutiu", "*No has de parlar amb este advocat, sinó amb l'altre.*"], ["*sinó que*", "substitutiu + oració", "*No t'he dit que calles, sinó que parles més baixet.*"], ["*si no*", "condició negativa", "*Si no aproves, no vindràs de viatge.*"], ["*si no*", "'en cas contrari'", "*Vine a les deu; si no, a les onze.*"]]}}, {"title": "Locucions condicionals", "text": "La condicional bàsica és ***si***. Per a matisar la condició, la llengua formal disposa de locucions que van amb **subjuntiu**: ***sempre que***, ***a condició que*** (o *amb la condició que*), ***en cas que***, ***posat que***, ***només que***, *sols que*, ***amb que*** i ***a menys que***. Amb indicatiu, *sempre que* és temporal (= *cada vegada que*).", "examples": ["T'ho diré **sempre que** et comprometes a callar.", "Els ho confessà **amb la condició que** no ho contaren a ningú.", "Pots demanar un certificat **en cas que** el necessites.", "**Amb que** Neus parle, tot s'aclarirà."], "watch": [{"wrong": "Te'l deixe sempre i quan me'l tornes.", "right": "Te'l deixe sempre que (o a condició que) me'l tornes."}, {"wrong": "En cas de que plore, telefona'm.", "right": "En cas que plore, telefona'm."}]}, {"title": "Mode i temps en les condicionals amb *si*", "text": "Amb ***si***, la condició **real** va en **indicatiu** (mai en present de subjuntiu ni en futur). La condició **irreal** porta **imperfet de subjuntiu** i la principal, condicional. Si la situació no es va produir en el passat, **plusquamperfet de subjuntiu** i **condicional perfet**.", "table": {"head": ["classe", "condició", "exemple"], "rows": [["real", "indicatiu", "*Si ho aprove tot, me n'aniré d'acampada.*"], ["irreal", "imperfet de subjuntiu", "*Si ho aprovara tot, me n'aniria d'acampada.*"], ["irreal de passat", "plusquamperfet de subjuntiu", "*Si ho haguera aprovat tot, me n'hauria anat d'acampada.*"]]}, "watch": [{"wrong": "Si tinga temps, t'ajudaré.", "right": "Si tinc temps, t'ajudaré."}]}], "remember": ["*Per què*: interrogatiu de causa o relatiu (= *pel qual*); *perquè*: conjunció; *per a què*: finalitat; *el perquè*: el motiu.", "*Perquè* + indicatiu és causal; *perquè* + subjuntiu és final. En registre formal, *perquè* i no *per a que*.", "*Doncs* és consecutiu; per a la causa, *perquè*, *ja que*, *atés que* o *puix que*.", "*Sinó* substituïx el que s'ha negat; *si no* és condició negativa o 'en cas contrari'.", "*Sempre que*, *a condició que*, *en cas que* o *posat que* + subjuntiu, sense *de* davant de *que*."], "sources": [{"gram": "GVB", "section": "28.3.2", "title": "Què", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=28_3_2"}, {"gram": "GVB", "section": "29.3", "title": "Què", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=29_3"}, {"gram": "GVB", "section": "33.2", "title": "L'elisió de preposicions àtones", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=33_2"}, {"gram": "GVB", "section": "41.3.4", "title": "Les conjuncions adversatives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_3_4"}, {"gram": "GVB", "section": "41.4.2", "title": "Les conjuncions condicionals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_4_2"}, {"gram": "GVB", "section": "41.4.4", "title": "Les conjuncions causals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_4_4"}, {"gram": "GVB", "section": "41.4.5", "title": "Les conjuncions finals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_4_5"}, {"gram": "GVB", "section": "41.4.6", "title": "Les conjuncions consecutives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_4_6"}, {"gram": "GNV", "section": "24.3.2", "title": "Els relatius que, qui, què i article + qual", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=24_3_2"}, {"gram": "GNV", "section": "34.4.4", "title": "Les conjuncions adversatives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_4_4"}, {"gram": "GNV", "section": "34.5.2", "title": "Les conjuncions condicionals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_5_2"}, {"gram": "GNV", "section": "34.5.4", "title": "Les conjuncions causals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_5_4"}, {"gram": "GNV", "section": "34.5.5", "title": "Les conjuncions finals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_5_5"}, {"gram": "GNV", "section": "34.5.6", "title": "Les conjuncions consecutives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_5_6"}]}},
  {"type": "c1_mor_connectors", "lesson": {"intro": "Aprendràs a enllaçar les idees d'un text formal amb connectors d'ordenació, addició, contrast, reformulació, exemplificació, conseqüència i conclusió, i a substituir els calcs més freqüents per les formes genuïnes.", "blocks": [{"title": "Què és un connector textual", "text": "Les conjuncions unixen oracions dins d'una mateixa frase; els **adverbis i locucions textuals** (*tanmateix*, *a més*, *per consegüent*...) **connecten** l'oració amb el discurs previ i ordenen la informació. Poden ocupar **diverses posicions** i es combinen amb *i* o *però*. Com que són parentètics, van **entre comes**, i davant d'ells sol anar **punt i coma** quan unixen oracions llargues.", "examples": ["No ha estudiat gens; **tanmateix**, ha aprovat totes les assignatures.", "Ha aprovat, **tanmateix**, totes les assignatures.", "No ha estudiat gens i, **tanmateix**, ha aprovat totes les assignatures."], "watch": [{"wrong": "No ha estudiat gens i no obstant això ha aprovat.", "right": "No ha estudiat gens i, no obstant això, ha aprovat."}]}, {"title": "Ordenar i distribuir", "text": "Per a **ordenar** les parts del discurs: *primerament*, *en primer lloc*, *primer de tot*, *a continuació*, *finalment*, *per últim*. Per a **distribuir** o alternar elements, construccions paral·leles com ***d'una banda... d'altra banda***, *ara... ara*, ***bé... bé***, ***ja... ja***, *siga... siga*.", "table": {"head": ["funció", "connectors", "exemple"], "rows": [["ordenació", "*en primer lloc*, *a continuació*, *per últim*", "*En primer lloc, ens va parlar dels objectius.*"], ["distribució", "*d'una banda... d'altra banda*", "*D'una banda és car; d'altra banda, és necessari.*"], ["alternança", "*bé... bé*, *ja... ja*, *siga... siga*", "*Ja per un motiu, ja per un altre, no ho ha fet.*"]]}}, {"title": "Sumar i contrastar", "text": "Per a **sumar** o **equiparar**: ***a més***, ***igualment***, ***així mateix***, *paral·lelament*. Per a **oposar** una idea a l'anterior: ***tanmateix***, ***no obstant això*** (o *això no obstant*), ***amb tot***, ***així i tot***, *en canvi*, *per contra* i ***ara bé***, que introduïx una restricció. *Altrament* vol dir 'si no, en cas contrari'.", "examples": ["Recordem, **igualment**, que no es pot fumar.", "La pel·lícula dura tres hores; **amb tot**, no es fa llarga.", "La proposta és bona. **Ara bé**, caldrà revisar-ne el cost."], "watch": [{"wrong": "És car; sin embargo, el comprarem.", "right": "És car; tanmateix (o no obstant això), el comprarem."}, {"wrong": "El pis és cèntric i, encima, té llum.", "right": "El pis és cèntric i, a més, té llum."}]}, {"title": "Reformular, exemplificar i especificar", "text": "Per a **reformular** o aclarir: ***és a dir***, ***o siga***, ***en altres paraules***, *dit d'una altra manera*. Per a **exemplificar**: ***per exemple***, ***com ara***, ***posem per cas***. Per a **especificar** o remarcar: ***sobretot***, *especialment*, *particularment*. Per a **generalitzar** o confirmar: *en general*, *generalment*, *en efecte*.", "examples": ["És plurilingüe, **és a dir**, parla més de dues llengües.", "Toca diversos instruments, **com ara** el piano o la guitarra.", "Les pluges provoquen el caos, **sobretot** en les zones costaneres."]}, {"title": "Conseqüència, resum i conclusió", "text": "Per a la **conseqüència**: ***per tant***, ***per consegüent***, *consegüentment*, ***en conseqüència***, *així doncs* i ***doncs***. Per a **resumir** i **concloure**: *en resum*, *en síntesi*, ***en conclusió***, ***en definitiva***, ***al cap i a la fi***, *en fi*, *per acabar*. En la recapitulació oral, no uses l'infinitiu com a verb principal.", "table": {"head": ["funció", "connectors"], "rows": [["conseqüència", "*per tant*, *per consegüent*, *en conseqüència*, *doncs*"], ["resum", "*en resum*, *en síntesi*"], ["conclusió", "*en conclusió*, *en definitiva*, *al cap i a la fi*, *per acabar*"]]}, "watch": [{"wrong": "Per a concloure, dir que estem molt satisfets.", "right": "Per a concloure, hem de dir (o cal dir) que estem molt satisfets."}]}, {"title": "Calcs que cal evitar", "text": "Molts connectors defectuosos són **calcs** del castellà, sovint amb l'article neutre *lo*. La GVB proposa alternatives genuïnes per a cadascun. Tampoc són adequats en un text formal *sin embargo*, *pues*, *bueno*, *entonces*, ni les expressions ***a nivell de*** (amb el valor de 'pel que fa a') i ***en base a***.", "table": {"head": ["evita", "usa"], "rows": [["*per lo tant*", "*per tant*"], ["*per lo general*", "*generalment*, *en general*"], ["*per lo demés*", "*d'altra banda*, *això a banda*"], ["*de lo contrari*", "*si no*, *altrament*, *d'una altra manera*"], ["*en lo referent a*, *en quant a*", "*pel que fa a*, *respecte a*, *quant a*"], ["*per lo menys*", "*almenys*"], ["*per lo vist*", "*segons sembla*, *pel que es veu*"], ["*a nivell de*, *en base a*", "*pel que fa a*, *a partir de*, *sobre la base de*"]]}}], "remember": ["Els connectors textuals enllacen amb el discurs previ, poden canviar de posició i van entre comes.", "Contrast: *tanmateix*, *no obstant això*, *amb tot*, *així i tot*, *ara bé*; mai *sin embargo*.", "Reformulació: *és a dir*, *o siga*; exemplificació: *per exemple*, *com ara*, *posem per cas*.", "Conseqüència i conclusió: *per tant*, *per consegüent*, *en conseqüència*, *en definitiva*, *al cap i a la fi*.", "Fora el *lo*: *per tant*, *generalment*, *altrament*, *pel que fa a*, *almenys*."], "sources": [{"gram": "GVB", "section": "15.3.1", "title": "Usos de la coma", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_3_1"}, {"gram": "GVB", "section": "15.4", "title": "El punt i coma", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_4"}, {"gram": "GVB", "section": "19.5.2", "title": "Altres usos", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=19_5_2"}, {"gram": "GVB", "section": "38.3", "title": "Els adverbis textuals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=38_3"}, {"gram": "GVB", "section": "41.3.3", "title": "Les conjuncions distributives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_3_3"}, {"gram": "GVB", "section": "41.3.4", "title": "Les conjuncions adversatives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_3_4"}, {"gram": "GVB", "section": "41.4.6", "title": "Les conjuncions consecutives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_4_6"}, {"gram": "GNV", "section": "15.5", "title": "L'article neutre", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=15_5"}, {"gram": "GNV", "section": "27.8", "title": "Els adverbis textuals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=27_8"}, {"gram": "GNV", "section": "28.6.2", "title": "Precisions sobre l'ús de les formes no personals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_6_2"}, {"gram": "GNV", "section": "34.3", "title": "Les conjuncions i altres classes de paraules", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_3"}, {"gram": "GNV", "section": "34.4.3", "title": "Les conjuncions distributives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_4_3"}]}},
  {"type": "c1_mor_verbs_irregulars", "lesson": {"intro": "Aprendràs a conjugar amb seguretat els verbs velaritzats i els que pateixen més interferències (*admetre*, *rebre*, *ocórrer*, *garantir*, *trair*...), les famílies en *-metre*, *-córrer*, *-fondre*, *-batre*, *-rompre* i *-cloure*, i les formes més delicades de *cabre*, *caldre*, *saber* i *veure*.", "blocks": [{"title": "Velaritzats: on va la velar i on no", "text": "Els velaritzats porten *-c* / *-g-* en el *jo* del present, en tot el **present de subjuntiu**, en l'imperatiu 3, 4 i 6, en el **passat simple**, en l'**imperfet de subjuntiu** i, normalment, en el participi. Usa el subjuntiu valencià: ***vinga***, ***tinga***, ***puga***, ***valga***. Però **cap gerundi** porta velar, i les persones 4 i 5 del present tampoc: *bevem*, no *beguem*.", "table": {"head": ["verb", "subjuntiu", "imperf. subj.", "participi"], "rows": [["*vindre*", "*vinga*", "*vinguera*", "*vingut*"], ["*tindre*", "*tinga*", "*tinguera*", "*tingut*"], ["*valdre*", "*valga*", "*valguera*", "*valgut*"], ["*doldre*", "*dolga*", "*dolguera*", "*dolgut*"]]}, "watch": [{"wrong": "Estava diguent la veritat.", "right": "Estava dient la veritat."}]}, {"title": "*Rebre*, *concebre*, *percebre*; *admetre* i els verbs en *-metre*", "text": "***Rebre***, ***concebre*** i ***percebre*** són de la **segona** conjugació, com *batre*: *rep*, *rebem*, *reba*, *rebut*; no són incoatius ni es conjuguen com en castellà. ***Admetre*** i tots els verbs en ***-metre*** (*permetre*, *cometre*, *transmetre*, *sotmetre*, *ometre*) també seguixen *batre*, però fan el participi en ***-és***.", "table": {"head": ["verb", "present", "subjuntiu", "participi"], "rows": [["*rebre*", "*rep*, *rebem*, *reben*", "*reba*, *rebes*", "*rebut*"], ["*concebre*", "*concep*, *conceben*", "*conceba*", "*concebut*"], ["*admetre*", "*admet*, *admeten*", "*admeta*", "*admés*, *admesa*"], ["*permetre*", "*permet*, *permeten*", "*permeta*", "*permés*, *permesa*"]]}, "watch": [{"wrong": "No s'admitixen devolucions.", "right": "No s'admeten devolucions."}, {"wrong": "No està permitit.", "right": "No està permés."}]}, {"title": "*-córrer*, *-fondre*, *-batre*, *-rompre*, *-cloure*", "text": "Les **famílies** conserven la conjugació del verb base. Els de ***córrer*** (*ocórrer*, *recórrer*, *concórrer*, *incórrer*) són velaritzats: *ocórrega*, *ocorregué*, *ocorregut*. Els de ***fondre*** fan *confonc* i *confós* (*o* tancada). Els de ***batre*** són regulars: *debat*, *combatut*. Els de ***rompre***, participi en *-ut*. I els de ***cloure***, *conclòs* (*o* oberta) i imperfet *incloïa*.", "table": {"head": ["família", "exemple", "participi"], "rows": [["*-córrer*", "*ocórrer*: *ocorre*, *ocórrega*", "*ocorregut*, *incorregut*"], ["*-fondre*", "*confondre*: *confonc*, *confonga*", "*confós*, *difós*"], ["*-batre*", "*debatre*: *debat*, *debaten*", "*debatut*, *combatut*"], ["*-rompre*", "*interrompre*: *interromp*, *interrompa*", "*interromput*, *corromput*"], ["*-cloure*", "*concloure*: *concloc*, *concloga*, *incloïa*", "*conclòs*, *inclòs*, *exclòs*"]]}, "watch": [{"wrong": "Ha incurrit en una contradicció.", "right": "Ha incorregut en una contradicció."}]}, {"title": "*Garantir*, *florir*, *trair* i *telefonar*", "text": "***Garantir***, ***florir*** i ***trair*** són **incoatius**: *garantix*, *garantisca*; *florix*, *florit*. En *trair*, la *i* fa hiat: porta **dièresi** quan cal (*traïa*, *traït*), però **no** en l'infinitiu, el gerundi, el futur ni el condicional (*trair*, *traint*, *trairà*). ***Telefonar*** és un verb **regular** de la primera conjugació: *telefone*, *telefones*.", "examples": ["Cal que l'administració **garantisca** els drets de tothom.", "Els ametlers ja han **florit**.", "M'ha **traït** la persona en qui més confiava; si continua així, et **trairà** a tu.", "Espere que em **telefones** demà."], "watch": [{"wrong": "Espere que em telefonees.", "right": "Espere que em telefones."}]}, {"title": "*Cabre*, *caldre*, *saber* i *veure* (o *vore*)", "text": "***Cabre*** fa *cap* en la 3a persona. ***Caldre*** **concorda** amb el subjecte (*calen tres persones*) i fa formes velaritzades: *calga*, *calgué*, *calguera*, *calgut*. ***Saber*** té el subjuntiu *sàpia*, *sàpies*. ***Veure*** (o *vore*) fa *veig*, *veiem*, *veja*, *veia*, el participi *vist* i el gerundi *veient*.", "table": {"head": ["verb", "formes clau"], "rows": [["*cabre*", "*cap*, *cabem*, *caben*; *cabut*"], ["*caldre*", "*cal*, *calen*; *calia*; *calga*; *calguera*; *calgut*"], ["*saber*", "*sé*, *saps*, *sap*; *sàpia*, *sàpies*, *sapiem*; *sabut*"], ["*veure* / *vore*", "*veig*, *veiem*; *veja*, *vegem*; *veia*; *vist*; *veient*"]]}, "watch": [{"wrong": "Ara vegem la pel·lícula.", "right": "Ara veiem la pel·lícula. (*vegem* és subjuntiu)"}, {"wrong": "Estàvem vegent el partit.", "right": "Estàvem veient el partit."}]}], "remember": ["Subjuntiu valencià velaritzat: *vinga*, *tinga*, *valga*; cap gerundi amb velar (*dient*, *veient*).", "*Rebre*, *concebre* i *percebre* seguixen *batre*: *rep*, *reba*, *rebut*.", "Verbs en *-metre* i *-fondre*: participi en *-és* / *-ós*: *admés*, *permés*, *confós*, *difós*.", "*-córrer* → *ocorregut*; *-rompre* → *interromput*; *-cloure* → *conclòs*, *incloïa*; *-batre* → *debatut*.", "*Garantir*, *florir* i *trair* són incoatius: *garantix*, *florix*, *traïx*; però *trairà* sense dièresi.", "*Calen* tres persones; *sàpia*, *sàpies*; *veiem* (indicatiu) i *vegem* (subjuntiu)."], "sources": [{"gram": "GVB", "section": "1.2.1", "title": "Les vocals tòniques", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=1_2_1"}, {"gram": "GVB", "section": "8.1", "title": "Usos de la dièresi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=8_1"}, {"gram": "GVB", "section": "8.2", "title": "Estalvi en l'ús de la dièresi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=8_2"}, {"gram": "GVB", "section": "39.3.2", "title": "Els verbs regulars i els verbs irregulars", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=39_3_2"}, {"gram": "GNV", "section": "29.3.2", "title": "Els verbs incoatius i els purs de la tercera conjugació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=29_3_2"}, {"gram": "GNV", "section": "29.4.2", "title": "Model del verb batre", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=29_4_2"}, {"gram": "GNV", "section": "29.4.3", "title": "Model del verb servir", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=29_4_3"}, {"gram": "GNV", "section": "29.5", "title": "Precisions sobre el polimorfisme verbal", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=29_5"}, {"gram": "GNV", "section": "30.2.2", "title": "Verbs amb alternances consonàntiques al final del radical", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_2_2"}, {"gram": "GNV", "section": "30.2.3", "title": "Tendència a la generalització de formes velaritzades", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_2_3"}, {"gram": "GNV", "section": "30.2.4.2", "title": "Verbs amb i consonàntica en formes del present d'indicatiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_2_4_2"}, {"gram": "GNV", "section": "30.2.4.4", "title": "Els participis forts", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_2_4_4"}]}},
  {"type": "c1_mor_verbs_formes", "lesson": {"intro": "Aprendràs les formes poc usuals de verbs com *complaure*, *jaure*, *moldre*, *morir*, *oir* o *romandre*, els verbs que admeten el model pur i l'incoatiu, les formes no velaritzades pròpies del registre formal i a reconéixer les desinències d'altres parlars.", "blocks": [{"title": "Formes poc usuals de verbs irregulars", "text": "Alguns verbs de poc ús tenen formes que cal **memoritzar**. ***Complaure*** i ***jaure*** són velaritzats (*complac*, *complagut*; *jac*, *jaga*, *jagut*) i *jaure* fa l'imperfet fort *jeia*. ***Moldre*** i ***fondre*** també velaritzen (*molc*, *molga*; *fonc*, *fonga*), però el participi és fort: *molt*, *fos*. ***Romandre*** fa *romanc*, *romanga* i *romàs*. ***Morir*** fa *muira* en subjuntiu i *mort* en participi.", "table": {"head": ["verb", "present", "subjuntiu", "participi"], "rows": [["*complaure*", "*complac*, *complau*", "*complaga*", "*complagut*"], ["*jaure*", "*jac*, *jau*", "*jaga*", "*jagut*"], ["*moldre*", "*molc*, *mol*", "*molga*", "*molt*"], ["*romandre*", "*romanc*, *roman*", "*romanga*", "*romàs*, *romasa*"], ["*morir*", "*mor*, *moren*", "*muira*, *muires*", "*mort*"]]}, "watch": [{"wrong": "El gos jaïa davall de la taula.", "right": "El gos jeia davall de la taula."}]}, {"title": "*Imprimir*, *lluir*, *oir*, *cruixir*, *escopir*, *rostir*", "text": "***Imprimir*** és incoatiu (*imprimix*) però té participi sigmàtic: ***imprés***, *impresa*. En ***lluir*** i ***oir*** la *i* fa hiat: porta **dièresi** en *lluïx*, *lluït*, *oïa*, *oït*, però no en l'infinitiu, el gerundi, el futur ni el condicional (*lluint*, *oirà*). ***Cruixir*** fa *cruixit*. ***Escopir*** i ***rostir***, en el model pur, alternen *u* tònica i *o* àtona: *escup* / *escopim*, *rust* / *rostim*.", "examples": ["Els programes ja estan **impresos**.", "Este vestit **lluïx** molt; amb la corbata **lluiràs** més.", "Des de casa s'**oïa** la música, però ningú no ha **oït** els crits.", "Qui **escup** cap amunt, a la cara li cau."], "watch": [{"wrong": "Ja tenim els cartells imprimuts.", "right": "Ja tenim els cartells impresos."}]}, {"title": "Verbs amb model pur i incoatiu", "text": "Uns quants verbs de la tercera conjugació admeten **dos models**: el **pur**, amb alternança vocàlica (*i/e*, *u/o*), i l'**incoatiu**. Així, ***afegir*** fa *afig* o *afegix*; ***llegir***, *llig* o *llegix*; ***vestir***, *vist* o *vestix*. En el model pur, la vocal tancada apareix quan és **tònica** (*afig*, *afija*) i la vocal *e* o *o* quan és **àtona** (*afegim*, *cosiu*).", "table": {"head": ["verb", "model pur", "model incoatiu"], "rows": [["*afegir*", "*afig*, *afija*, *afegim*", "*afegix*, *afegisca*"], ["*llegir*", "*llig*, *llija*, *llegim*", "*llegix*, *llegisca*"], ["*vestir*", "*vist*, *vista*, *vestim*", "*vestix*, *vestisca*"]]}, "watch": [{"wrong": "Nosaltres lligim el diari.", "right": "Nosaltres llegim el diari."}]}, {"title": "Formes sense velaritzar: *dorm*, *perd*, *sent*", "text": "En la llengua parlada s'han estés formes velaritzades a *perdre* i als verbs purs de la tercera: *perc*, *perga*, *pergué*; *dorc*, *dorga*; *senc*, *senga*. La GNV considera que el **model no velaritzat** és el **regular**, el **clàssic** i el que convé usar en els **registres formals**: *perd*, *perda*, *perdé*; *dorm*, *dorma*; *sent*, *senta*. Les formes velaritzades poden servir per a reproduir un llenguatge **espontani**.", "table": {"head": ["", "formal (no velaritzat)", "col·loquial (velaritzat)"], "rows": [["*perdre*", "*perd*, *perda*, *perdé*", "*perc*, *perga*, *pergué*"], ["*dormir*", "*dorm*, *dorma*, *dormen*", "*dorc*, *dorga*, *dorguen*"], ["*sentir*", "*sent*, *senta*, *senten*", "*senc*, *senga*, *senguen*"]]}, "watch": [{"wrong": "Espere que no pergues el tren. (en un text formal)", "right": "Espere que no perdes el tren."}]}, {"title": "Variació diatòpica de les desinències", "text": "Les desinències verbals **varien segons el parlar**, i cal **reconéixer-les, no corregir-les**. En la major part del valencià diem *jo cante*; en el valencià **septentrional**, *jo canto*; en **balear**, *jo cant*. En el subjuntiu, en Catalunya i les Balears s'usa *-i*: *que jo canti*. L'imperfet de subjuntiu pot ser en *-ra* (*cantara*) o en *-s* (*cantés*, *cantàs*), i el passat perifràstic admet *vam* i *vàrem*.", "table": {"head": ["forma general valenciana", "altres variants acceptables"], "rows": [["*(jo) cante*", "*canto* (septentrional), *cant* (balear)"], ["*(que jo) cante*", "*canti* (Catalunya, Balears)"], ["*cantara*, *batera*", "*cantés* / *cantàs*, *batés*"], ["*servix*, *servixen*", "*serveix*, *serveixen*"], ["*vam cantar*", "*vàrem cantar*"]]}, "examples": ["Jo també ho **hauria** (o **haguera**) fet, si m'ho hagueren dit."]}, {"title": "Formes que convé evitar en l'estàndard", "text": "Algunes variants són vives però **no** són les adequades en el **registre formal**. Les formes de subjuntiu en *-am*, *-au* (*tingam*, *tingau*, *vejam*) es mantenen en parlars valencians, però en l'estàndard s'usen *tinguem*, *tingueu*, *vegem*. L'increment *-esc* (*servesc*, *servesca*) se sent antic. I, encara que es pronuncie sovint palatal, s'escriu **-sc**: *nasc*, *cresc*, *visc*.", "watch": [{"wrong": "Cal que ho tingam en compte.", "right": "Cal que ho tinguem en compte."}, {"wrong": "Vixc a Gandia des de fa anys.", "right": "Visc a Gandia des de fa anys."}]}], "remember": ["*Jac*, *jeia*, *jagut*; *molc*, *molt*; *fonc*, *fos*; *romanc*, *romàs*; *muira*, *mort*; *complagut*.", "*Imprés*, *impresa*; *lluïx*, *oïa*, *oït* amb dièresi, però *lluiràs*, *oirà*, *lluint* sense.", "*Afegir*, *llegir* i *vestir* admeten model pur (*afig*, *llig*, *vist*) i incoatiu (*afegix*, *llegix*, *vestix*).", "En registre formal, formes no velaritzades: *dorm*, *perd*, *sent*; *dorma*, *perda*, *senta*; *perdé*.", "*Cante*, *canto*, *cant* i *canti* són variants dialectals legítimes: reconeix-les, no les corregisques.", "*Cantara* = *cantés*; *hauria fet* = *haguera fet*; *vam* = *vàrem*; però *tinguem* millor que *tingam*."], "sources": [{"gram": "GVB", "section": "39.3.1", "title": "Les tres conjugacions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=39_3_1"}, {"gram": "GVB", "section": "39.3.2", "title": "Els verbs regulars i els verbs irregulars", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=39_3_2"}, {"gram": "GNV", "section": "29.3.2", "title": "Els verbs incoatius i els purs de la tercera conjugació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=29_3_2"}, {"gram": "GNV", "section": "29.4.4", "title": "Model del verb sentir", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=29_4_4"}, {"gram": "GNV", "section": "29.5", "title": "Precisions sobre el polimorfisme verbal", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=29_5"}, {"gram": "GNV", "section": "30.1", "title": "Conceptes generals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_1"}, {"gram": "GNV", "section": "30.2.1", "title": "Verbs amb alternances vocàliques en el radical", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_2_1"}, {"gram": "GNV", "section": "30.2.2", "title": "Verbs amb alternances consonàntiques al final del radical", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_2_2"}, {"gram": "GNV", "section": "30.2.3", "title": "Tendència a la generalització de formes velaritzades", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_2_3"}, {"gram": "GNV", "section": "30.2.4.1", "title": "Verbs amb imperfets forts", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_2_4_1"}, {"gram": "GNV", "section": "30.2.4.2", "title": "Verbs amb i consonàntica en formes del present d'indicatiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_2_4_2"}, {"gram": "GNV", "section": "30.2.4.4", "title": "Els participis forts", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_2_4_4"}, {"gram": "GNV", "section": "30.3", "title": "Els principals verbs irregulars", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_3"}]}},
  {"type": "c1_mor_verbs_construccions", "lesson": {"intro": "Aprendràs a usar els verbs en construccions transitives i intransitives, personals i impersonals (*haver-hi*, *fer*, passiva pronominal) i pronominals i no pronominals, amb la concordança i el règim que fixa la GNV.", "blocks": [{"title": "*Haver-hi* i altres impersonals", "text": "Les oracions **impersonals** no tenen subjecte: *Plou*, *Ha pedregat*, *És molt tard*, *Fa fred*, *Fa tres anys que viu ací*. En ***haver-hi***, el sintagma nominal es comporta com un **complement directe**; per això l'ús tradicional no fa concordança. La GNV accepta *hi han*, però en **registre formal** és més adequat *hi ha*, *hi havia*, *hi haurà*.", "examples": ["A ma casa **hi ha** més cadires. (preferible en registre formal)", "Ahir **hi havia** molts espectadors.", "**Fa** molt de fred; **fa** temps que no el veig."], "watch": [{"wrong": "L'any que ve hi hauran eleccions. (text formal)", "right": "L'any que ve hi haurà eleccions."}]}, {"title": "Passiva perifràstica i passiva pronominal", "text": "La passiva amb ***ser* + participi** sona natural en futur o en passat (*serà construït*, *va ser presentat*), però resulta **anòmala en present i imperfet**, i no admeten passiva els verbs estatius (*tindre*, *saber*, *patir*). En la llengua general s'usa més la **passiva pronominal**, en què el SN és el **subjecte** i el verb **hi concorda**, la 3a persona del plural o la dislocació.", "examples": ["Enguany **s'han construït** molts edificis.", "Ahir **es va presentar** el dictamen. / Ahir **van presentar** el dictamen.", "El dictamen, **el** van presentar ahir els ponents."], "watch": [{"wrong": "Es lloga pisos.", "right": "Es lloguen pisos."}, {"wrong": "El nou museu és construït per una empresa valenciana.", "right": "El nou museu el construïx una empresa valenciana."}]}, {"title": "Transitius, intransitius i inacusatius", "text": "Molts **transitius** poden usar-se sense CD (**ús absolut**: *Ja no menja*), i alguns **intransitius** admeten un **acusatiu intern** (*Va viure una vida intensa*). Els verbs de **mesura** (*pesar*, *costar*, *durar*) porten un CD que expressa quantitat. Els **inacusatius** (*arribar*, *eixir*, *nàixer*, *morir*, *caldre*, *faltar*, *ocórrer*) tenen un subjecte que sovint va **posposat**, però el verb **hi concorda**.", "table": {"head": ["tipus", "exemple"], "rows": [["ús absolut", "*Menja molt.*"], ["acusatiu intern", "*Plorava llàgrimes amargues.*"], ["CD de mesura", "*Mesura dos metres.*"], ["inacusatiu", "*Han arribat uns parents meus. Falten dos cadires.*"]]}, "watch": [{"wrong": "Ha ocorregut coses molt estranyes.", "right": "Han ocorregut coses molt estranyes."}]}, {"title": "Concordança: col·lectius i persona", "text": "Amb **noms col·lectius** el verb vacil·la, però en general es preferix la **concordança formal** (*El professorat accepta*; *La mitat dels alumnes ha protestat*). En les **atributives** amb un col·lectiu i un plural es fa pel **sentit**: *Aquella multitud són treballadors*. La concordança de persona també pot ser pel sentit: *Els estudiants som responsables*; *Cap de vosaltres no anirà* (o *anireu*).", "examples": ["Una colla de castellers **ha participat** en la festa.", "Aquella multitud **són** treballadors del port.", "Els estudiants **som** molt responsables."]}, {"title": "Verbs pronominals que canvien de règim o de significat", "text": "Alguns verbs canvien de **construcció** si són pronominals: ***oblidar*** i ***recordar*** porten **CD**, però ***oblidar-se*** i ***recordar-se*** porten **complement de règim** amb *de* (pronominalitzable amb *en*). Altres, com ***atrevir-se a***, ***decidir-se a*** / ***per***, ***desviure's per***, ***penedir-se de*** o ***burlar-se de***, són pronominals amb règim fix.", "table": {"head": ["no pronominal", "pronominal"], "rows": [["*He oblidat la cita.*", "*M'he oblidat **de** la cita.*"], ["*Vaig recordar el que havia promés.*", "*Em vaig recordar **del** que havia promés.*"], ["*Ha decidit ajornar-ho.*", "*S'ha decidit **pel** model més econòmic.*"]]}, "watch": [{"wrong": "No t'oblides la cita.", "right": "No t'oblides de la cita. / No oblides la cita."}]}, {"title": "Pronominals amb *en* i *hi* lexicalitzats", "text": "Els verbs de moviment amb ***en*** lexicalitzat (*anar-se'n*, *eixir-se'n*, *pujar-se'n*, *vindre-se'n*) indiquen **desplaçament des d'un lloc**: *me'n vaig* és 'deixe el lloc on soc'. *Eixir-se'n* també vol dir 'vessar'. Amb ***hi*** lexicalitzat, el verb adquirix un sentit nou: *veure-s'hi* ('tindre vista'), *trobar-s'hi* ('sentir-se a gust'), *no s'hi val* ('no està permés').", "examples": ["Ja és tard: **me'n vaig**.", "La xiqueta **se n'ha pujat** a casa.", "Abaixa el foc, que la llet **se n'ix**!", "Amb el vestit nou no **m'hi trobe**."]}], "remember": ["*Haver-hi* és impersonal: en registre formal, *hi ha*, *hi havia*, *hi haurà* sense concordança.", "Passiva pronominal amb concordança: *es lloguen pisos*, *s'han construït edificis*.", "La passiva amb *ser* sona anòmala en present i imperfet; millor la pronominal, la 3a plural o la dislocació.", "Els inacusatius (*faltar*, *ocórrer*, *arribar*) concorden amb el subjecte posposat: *falten dos cadires*.", "*Oblidar* / *recordar* + CD; *oblidar-se* / *recordar-se* + *de*: *me'n vaig oblidar*.", "*Anar-se'n*, *pujar-se'n*, *eixir-se'n* (desplaçament); *veure-s'hi*, *trobar-s'hi* (hi lexicalitzat)."], "sources": [{"gram": "GNV", "section": "8.5", "title": "L'oració", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=8_5"}, {"gram": "GNV", "section": "8.5.1", "title": "El predicat i els complements", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=8_5_1"}, {"gram": "GNV", "section": "8.5.2", "title": "La concordança", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=8_5_2"}, {"gram": "GNV", "section": "23.2.1", "title": "Els pronoms reflexius i no reflexius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_2_1"}, {"gram": "GNV", "section": "23.4.1", "title": "El pronom ne", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_4_1"}, {"gram": "GNV", "section": "23.4.2", "title": "El pronom hi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_4_2"}, {"gram": "GNV", "section": "32.1", "title": "Conceptes generals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=32_1"}, {"gram": "GNV", "section": "32.2", "title": "El complement directe i la transitivitat", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=32_2"}, {"gram": "GNV", "section": "32.4", "title": "El complement de règim", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=32_4"}, {"gram": "GNV", "section": "33.2.1", "title": "Predicacions no verbals primàries", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=33_2_1"}, {"gram": "GVB", "section": "27.2.1", "title": "Els pronoms reflexius i no reflexius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_2_1"}, {"gram": "GVB", "section": "27.4.1", "title": "El pronom ne", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_4_1"}, {"gram": "GVB", "section": "27.4.2", "title": "El pronom hi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_4_2"}]}},
  {"type": "c1_mor_perifrasis", "lesson": {"intro": "Aprendràs a expressar l'obligació, la probabilitat i la imminència amb les perífrasis i construccions que recomana l'AVL (*haver de*, *deure*, *caldre*, *estar a punt de*) i a evitar calcs com *tindre que*, *hi ha que* o *anar a* amb valor de futur.", "blocks": [{"title": "L'obligació: *haver de*, *caldre*, *deure*", "text": "La perífrasi general d'obligació és ***haver de* + infinitiu**: *Has d'aprofitar el temps*; en primera persona s'admeten ***he de*** i ***haig de*** (però *haig* només com a modal). Per a l'obligació **impersonal** s'usa ***caldre*** + infinitiu o ***caldre que*** + subjuntiu, o *ser necessari que*. ***Deure* + infinitiu** pot expressar obligació, sobretot amb **connotació moral**: *Els fills deuen obeir els pares*.", "table": {"head": ["construcció", "exemple", "valoració"], "rows": [["*haver de* + inf.", "*He* (o *haig*) *de dir-te una cosa.*", "general"], ["*caldre* + inf.", "*Cal presentar la sol·licitud.*", "impersonal"], ["*caldre que* + subj.", "*Cal que ens ho comuniqueu.*", "impersonal"], ["*deure* + inf.", "*A mi se'm deu atribuir la culpa.*", "obligació moral"], ["*tindre de* + inf.", "*Tinc d'eixir prompte.*", "correcta, poc usada"]]}, "watch": [{"wrong": "Haig cantat tota la nit.", "right": "He cantat tota la nit."}]}, {"title": "Calcs d'obligació: *tindre que* i *hi ha que*", "text": "La GNV i la GVB són clares: **no són acceptables** ***tindre que*** ni ***hi ha que***. En el seu lloc s'usa *haver de*, *caldre* o *ser necessari*. En canvi, ***tindre de*** és **correcta**, encara que poc usada. Recorda que *caldre que* i *ser necessari que* exigixen **subjuntiu**, i que si el verb principal va en passat, la subordinada va en imperfet de subjuntiu: *Calia que m'ho digueres*.", "watch": [{"wrong": "Tens que estudiar més.", "right": "Has d'estudiar més."}, {"wrong": "Hi ha que revisar el pressupost.", "right": "Cal revisar el pressupost."}, {"wrong": "Cal de presentar-ho demà.", "right": "Cal presentar-ho demà."}]}, {"title": "La probabilitat: *deure* + infinitiu", "text": "***Deure* + infinitiu** expressa una **suposició** o una deducció no confirmada, i és el recurs **més habitual en registre formal** (també s'usa el futur: *estaran dormint*). Mai no porta ***de***. Per a suposicions sobre el passat s'usa l'infinitiu compost (*deuen haver arribat*) o l'imperfet (*devia tindre vint anys*). *Deure* admet el **passat simple** però **no el perifràstic**: *Li ho degué dir ell*.", "examples": ["Ja **deuen haver arribat**.", "No els molestes, que ara **deuen estar sopant**.", "Quan la vaig conéixer, **devia tindre** uns vint anys.", "Li ho **degué dir** ell."], "watch": [{"wrong": "Deuen de ser les cinc.", "right": "Deuen ser les cinc."}, {"wrong": "Li ho va deure dir ell.", "right": "Li ho degué dir ell."}]}, {"title": "Altres valors d'*haver de*", "text": "A més de l'obligació, ***haver de*** pot expressar **deducció** (*Han de tindre la música molt forta perquè no contesten*) o **futur emfàtic** (*Entra la roba, que ha de ploure*). En **condicional**, atenua l'obligació i servix per a donar consells: *Hauríem de pensar en altres alternatives*. Com en tota perífrasi, els pronoms poden anar davant de l'auxiliar o darrere de l'infinitiu: *t'ho he de dir* / *he de dir-t'ho*.", "examples": ["**Han de tindre** la música molt forta. (deducció)", "Entra la roba, que **ha de ploure**. (futur emfàtic)", "**Hauríem de** pensar en altres alternatives. (consell)"]}, {"title": "La imminència: *estar a punt de* i *anar a*", "text": "La imminència s'expressa amb ***estar a punt de* + infinitiu**. ***Anar a* + infinitiu** no ha desenvolupat el valor de **futur** i s'usa poc en present, perquè es pot confondre amb el passat perifràstic: usa el **futur** o l'imperatiu. Sí que és correcte quan *anar* indica **moviment** o, en imperfet, una acció que **no s'arriba a fer**. ***Estar per*** expressa intenció o allò que està pendent de produir-se.", "table": {"head": ["calc", "alternativa"], "rows": [["*La comissió es va a reunir.*", "*La comissió es reunirà.*"], ["*Ara vos vaig a dir...*", "*Ara vos diré...*"], ["*Anem a veure...*", "*A veure...*"], ["*Calleu, que va a començar.*", "*Calleu, que està a punt de començar.*"]]}, "examples": ["**Anàvem a eixir** quan ha sonat el telèfon. (conat)", "Han tocat a la porta: **vaig a veure** qui és. (moviment)"]}, {"title": "Perífrasis de gerundi calcades", "text": "***Estar* + gerundi** és correcta quan es vol **remarcar la durada** o la repetició (*Estan estudiant des de fa quatre hores*), però convé evitar-la quan no hi ha eixe matís: *—Què fas? —Prepare el sopar*. També convé evitar ***portar*** i ***vindre*** + gerundi amb valor duratiu, calcats del castellà: és més genuí *Fa tres anys que estudia alemany*.", "watch": [{"wrong": "Porta tres anys estudiant alemany.", "right": "Fa tres anys que estudia alemany."}, {"wrong": "—Què fas? —Estic preparant el sopar. (sense èmfasi en la durada)", "right": "—Què fas? —Prepare el sopar."}]}], "remember": ["Obligació: *haver de* (*he* o *haig de*), *caldre* + infinitiu, *caldre que* + subjuntiu, *deure* (obligació moral).", "*Tindre que* i *hi ha que* no són acceptables; *tindre de* és correcta però poc usada.", "Probabilitat: *deure* + infinitiu, sense *de*: *deuen ser les cinc*, *deuen haver arribat*, *li ho degué dir*.", "*Haver de* també pot indicar deducció (*han de tindre*) o futur emfàtic (*ha de ploure*).", "Imminència: *estar a punt de*; *anar a* + infinitiu no és futur (*es reunirà*, *vos diré*, *a veure*).", "Evita *portar* / *vindre* + gerundi duratius i l'abús d'*estar* + gerundi."], "sources": [{"gram": "GVB", "section": "40.1", "title": "Introducció", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=40_1"}, {"gram": "GVB", "section": "40.2.1", "title": "Acabar de + infinitiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=40_2_1"}, {"gram": "GVB", "section": "40.2.3", "title": "Anar a + infinitiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=40_2_3"}, {"gram": "GVB", "section": "40.2.7", "title": "Deure + infinitiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=40_2_7"}, {"gram": "GVB", "section": "40.2.8", "title": "Estar per + infinitiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=40_2_8"}, {"gram": "GVB", "section": "40.2.9", "title": "Haver de + infinitiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=40_2_9"}, {"gram": "GVB", "section": "40.3.4", "title": "Estar + gerundi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=40_3_4"}, {"gram": "GNV", "section": "28.4.1", "title": "Els temps verbals d'indicatiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_4_1"}, {"gram": "GNV", "section": "30.2.2", "title": "Verbs amb alternances consonàntiques al final del radical", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_2_2"}, {"gram": "GNV", "section": "31.1", "title": "Conceptes generals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=31_1"}, {"gram": "GNV", "section": "31.2", "title": "Característiques sintàctiques", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=31_2"}, {"gram": "GNV", "section": "31.3", "title": "Les perífrasis modals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=31_3"}, {"gram": "GNV", "section": "31.4", "title": "Les perífrasis aspectuals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=31_4"}]}},
  {"type": "c1_mor_ser_estar", "lesson": {"intro": "Aprendràs a triar entre *ser* i *estar* segons l'atribut i el subjecte, a localitzar persones i coses amb el verb adequat, a usar *haver-hi* en les presentacionals i a construir la passiva perifràstica.", "blocks": [{"title": "Propietats amb *ser*, estats amb *estar*", "text": "La tria depén de l'**atribut** i del **subjecte**. Si l'atribut indica una **propietat** (origen, material, caràcter, classificació), s'usa ***ser***, siga quin siga el subjecte i la forma de l'atribut. Si indica un **estat transitori** d'un subjecte **animat**, l'ús general és ***estar***. A més, *estar* és **incompatible amb un atribut nominal**: amb un sintagma nominal, sempre *ser*.", "table": {"head": ["atribut", "subjecte animat", "subjecte inanimat"], "rows": [["propietat", "*Pau és valencià.*", "*La Terra és redona.*"], ["estat (adjectiu)", "*El mestre està malalt.*", "*La llet és* (o *està*) *calenta.*"], ["estat (participi, SP, adverbi)", "*La mare està gitada.*", "*La casa està tancada.*"]]}, "watch": [{"wrong": "Robert està un bon home.", "right": "Robert és un bon home."}]}, {"title": "Usos acceptats: no ho corregisques", "text": "Hi ha casos en què l'AVL admet **totes dues** opcions. Amb **subjectes inanimats** i adjectius d'estat, *ser* és l'ús **tradicional i genuí**, però *estar* s'ha estés: *el camp és* o *està ple de brossa*. L'**estat civil** s'ha vist com una propietat (*és casat*, *és viuda*, *és jubilat*), però hui també es concep com a transitori (*està casat*). En canvi, amb participis i adverbis referits a inanimats l'ús més estés és *estar*.", "examples": ["La llet **és** (o **està**) calenta.", "Ma tia **és** fadrina.", "Pere **és** (o **està**) casat.", "El pis que et vols comprar **està** molt bé."]}, {"title": "Localitzar: durada o no", "text": "En els usos **locatius**, el criteri és el **caràcter duratiu**. Si només situem algú o alguna cosa, sense interés per la durada, els registres formals trien ***ser***. Si destaquem la **permanència** en el lloc (*tot el dia*, *sempre*), ***estar***. En valencià col·loquial *estar* ha anat ocupant els contextos de *ser* per interferència, i la GNV recomana evitar-ho en la llengua formal.", "table": {"head": ["", "no duratiu", "duratiu"], "rows": [["persona", "*Quan he arribat, el teu fill era al carrer.*", "*El teu fill està tot el dia al carrer.*"], ["objecte", "*El llapis que busques és al calaix.*", "*El llapis ha estat sempre al calaix.*"]]}}, {"title": "Presentar un element: *haver-hi*", "text": "Les **construccions presentacionals** introduïxen un element nou en el discurs. L'ús tradicional és ***haver-hi***, que es conserva en frases fetes i refranys (*Qui hi ha per ací?*, *On hi ha el cos, hi ha la mort*). L'ús d'*estar* en estos contextos és molt general en la llengua parlada, però **convé evitar-lo** en els registres formals.", "watch": [{"wrong": "Fora està l'home que vingué ahir.", "right": "Fora hi ha l'home que vingué ahir."}, {"wrong": "Al baül està una de les figures més boniques que tinc.", "right": "Al baül hi ha una de les figures més boniques que tinc."}]}, {"title": "La passiva perifràstica: *ser* + participi", "text": "La passiva es forma amb ***ser* + participi**, que **concorda** amb el subjecte; l'agent va introduït per *per*. És normal en futur o passat, però resulta **anòmala en present i imperfet**, i no l'admeten els verbs estatius (*tindre*, *saber*). Com que és pròpia de l'escrit, la llengua general preferix la **passiva pronominal** o la tercera persona del plural. *Estar* + participi no és passiva: indica un **estat resultant**.", "examples": ["El dictamen **va ser presentat** ahir pels ponents.", "El gratacel **serà construït** per una empresa valenciana.", "Ahir **es va presentar** el dictamen. / Ahir **van presentar** el dictamen."], "watch": [{"wrong": "El nou museu és construït per una empresa valenciana.", "right": "El nou museu serà (o va ser) construït per una empresa valenciana."}]}, {"title": "Pronominalitzar l'atribut i el predicatiu", "text": "L'atribut de ***ser***, ***estar***, ***paréixer*** i ***semblar*** es pronominalitza amb ***ho***; el dels altres verbs quasicopulatius (*sentir-se*, *trobar-se*, *quedar-se*...) i el **complement predicatiu**, amb ***hi***. Recorda també que el predicatiu **concorda** amb el sintagma de què parla, i que *estar per* + infinitiu indica una acció **pendent** o una intenció.", "examples": ["—És més gran que tu? —Sí, **ho** és.", "Sa mare és magribina, però ell no s'**hi** sent.", "—Han arribat cansats? —Sí que **hi** han arribat.", "L'expedició ha arribat **contenta** a València.", "La sorpresa més gran **està per** arribar."]}], "remember": ["Propietat → *ser*; estat transitori d'un subjecte animat → *estar*.", "*Estar* no admet atributs nominals: *és un bon home*, mai *està un bon home*.", "Amb inanimats i adjectius d'estat, i amb l'estat civil, *ser* i *estar* són vàlids.", "Localització no durativa → *ser* (registre formal); permanència → *estar*; presentacional → *haver-hi*.", "Passiva: *ser* + participi concordat, millor en futur o passat; en la llengua general, passiva pronominal.", "Atribut de *ser*, *estar*, *paréixer* i *semblar* → *ho*; predicatiu i altres verbs → *hi*."], "sources": [{"gram": "GNV", "section": "33.1", "title": "Conceptes generals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=33_1"}, {"gram": "GNV", "section": "33.2.1", "title": "Predicacions no verbals primàries", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=33_2_1"}, {"gram": "GNV", "section": "33.2.2", "title": "Les predicacions no verbals secundàries", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=33_2_2"}, {"gram": "GNV", "section": "33.3", "title": "Els usos dels verbs *ser* i *estar*", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=33_3"}, {"gram": "GNV", "section": "33.3.1", "title": "Usos atributius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=33_3_1"}, {"gram": "GNV", "section": "33.3.2", "title": "Usos locatius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=33_3_2"}, {"gram": "GNV", "section": "32.2", "title": "El complement directe i la transitivitat", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=32_2"}, {"gram": "GNV", "section": "23.3", "title": "El pronom neutre", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_3"}, {"gram": "GVB", "section": "27.3", "title": "El pronom neutre", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_3"}, {"gram": "GVB", "section": "27.4.2", "title": "El pronom *hi*", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_4_2"}, {"gram": "GVB", "section": "40.2.8", "title": "*Estar per* + infinitiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=40_2_8"}, {"gram": "GVB", "section": "40.3.4", "title": "*Estar* + gerundi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=40_3_4"}]}},
  {"type": "c1_mor_formes_no_personals", "lesson": {"intro": "Aprendràs a usar l'infinitiu sense substantivacions forçades, a formar i concordar els participis irregulars, a evitar el gerundi de posterioritat i a conjugar els gerundis irregulars.", "blocks": [{"title": "Què indica cada forma", "text": "Les formes no personals no situen l'acció en el temps per elles mateixes; es distingixen per l'**aspecte**. El **gerundi** és imperfectiu (acció en curs, **simultània**), el **participi** és perfectiu (acció **acabada** i anterior) i l'**infinitiu** és la forma no marcada. Les formes compostes amb *haver* (*havent cantat*, *haver cantat*) indiquen anterioritat; el gerundi compost no necessita cap nexe.", "table": {"head": ["forma", "valor", "exemple"], "rows": [["gerundi", "simultaneïtat", "*Preparant el sopar, em vaig recordar del que t'havia promés.*"], ["participi", "acció acabada", "*Acabada la reunió, vam eixir a sopar.*"], ["infinitiu", "no marcat", "*Vol tornar demà.*"], ["gerundi compost", "anterioritat", "*Havent analitzat el tema, no hem arribat a cap solució.*"]]}}, {"title": "L'infinitiu: substantivació i ordes", "text": "Alguns infinitius són **verdaders substantius** (*dinar*, *sopar*, *somriure*, *el saber*) i admeten plural i article. Però quan l'infinitiu conserva complements verbals, **convé evitar l'article**: usa l'infinitiu sol, *el fet de* o un substantiu. A més, l'infinitiu sol **no** serveix per a donar ordes ni per a recapitular en un discurs: només és possible *a* + infinitiu (*A dormir!*).", "watch": [{"wrong": "El conéixer bé diferents llengües l'ha ajudat.", "right": "Conéixer bé diferents llengües l'ha ajudat. / El fet de conéixer..."}, {"wrong": "Per a concloure, dir que estem molt satisfets.", "right": "Per a concloure, hem de dir que estem molt satisfets."}, {"wrong": "No trepitjar la gespa.", "right": "Es prohibix trepitjar la gespa."}]}, {"title": "Participis forts", "text": "Molts verbs de la segona conjugació fan un participi **fort**. El més freqüent és el **sigmàtic** (*-s*): verbs en *-ndre* (excepte *vendre* i *pondre*), en *-metre*, en *-cloure* i *imprimir*. Compte: els derivats de ***tindre*** fan ***-tingut*** (*detingut*, *mantingut*), no **detés*. I en valencià ***omplir***, ***complir***, ***establir*** o ***oferir*** són regulars: *omplit*, *complit*, *establit*, *oferit*.", "table": {"head": ["tipus", "exemples"], "rows": [["en *-s*", "*comprés*, *imprés*, *exclòs*, *inclòs*, *encés*"], ["en *-t*", "*dit*, *dut*, *tret*, *distret*, *resolt*, *absolt*"], ["en *-st*", "*post*, *respost*, *vist*, *rist* (o *rigut*)"], ["en *-ert*", "*obert*, *cobert*"]]}}, {"title": "La concordança del participi", "text": "En els temps compostos, el participi **concorda** en gènere i nombre amb els pronoms **acusatius de tercera persona** (*lo*, *la*, *los*, *les*), sobretot en femení. També concorda quan hi ha un infinitiu darrere i el pronom s'anteposa al conjunt verbal. En canvi, **no concorda** amb els datius *li* i *els*.", "examples": ["—Queden mandonguilles? —No, me **les** he **acabades** al migdia.", "La pregunta, **l'**he **compresa**.", "Les respostes, no **les** he **sabudes** trobar.", "A les veïnes, **els** he **portat** un pastís. (datiu: sense concordança)"]}, {"title": "El gerundi: simultaneïtat, no conseqüència", "text": "Com que és imperfectiu, el gerundi expressa **simultaneïtat**. És **incorrecte** usar-lo per a una acció **posterior** o una conseqüència: cal una oració coordinada. Tampoc pot fer de **modificador d'un nom** amb valor de relativa especificativa; només s'admet amb valor de manera al costat de certs noms (*paraules*, *entrada*, *imatge*, *foto*...).", "watch": [{"wrong": "Caigué trencant-se la cama.", "right": "Caigué i es va trencar la cama."}, {"wrong": "Han aprovat un decret regulant els estudis.", "right": "Han aprovat un decret que regula els estudis."}], "examples": ["Les paraules del president **encoratjant** els jugadors foren molt efectives."]}, {"title": "Gerundis irregulars", "text": "**Cap gerundi no té velar**: les formes del tipus **caiguent*, **traguent* o **vegent* no són acceptables. Els verbs *caure*, *creure*, *jaure*, *seure*, *traure* i *veure* admeten la forma amb *i* (la més general en registres formals) i la forma sense *i*. Molts altres formen el gerundi sobre el radical de l'imperfet.", "table": {"head": ["infinitiu", "gerundi"], "rows": [["*beure*, *escriure*, *moure*, *ploure*", "*bevent*, *escrivint*, *movent*, *plovent*"], ["*traure*, *caure*, *jaure*", "*traient* o *traent*, *caient* o *caent*, *jaient* o *jaent*"], ["*estendre*, *prendre*", "*estenent*, *prenent*"], ["*vindre*, *tindre*", "*venint*, *tenint*"]]}}], "remember": ["Gerundi = simultaneïtat; participi = acció acabada; infinitiu = forma no marcada.", "Evita *el* + infinitiu amb complements: *Saber això m'alegra*; però *els sabers*, *el dinar*.", "Participis: *detingut*, *mantingut*, *distret*, *exclòs*, *imprés*; en valencià *omplit*, *complit*, *oferit*.", "El participi concorda amb *lo*, *la*, *los*, *les*: *me les he acabades*; no amb *li*, *els*.", "Mai gerundi de posterioritat ni gerundi adjectival: *Caigué i es va trencar la cama*.", "Gerundis sense velar: *bevent*, *traient*/*traent*, *estenent*, *venint*."], "sources": [{"gram": "GNV", "section": "28.6", "title": "Les formes no personals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_6"}, {"gram": "GNV", "section": "28.6.1", "title": "Caracterització general", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_6_1"}, {"gram": "GNV", "section": "28.6.2", "title": "Precisions sobre l'ús de les formes no personals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_6_2"}, {"gram": "GNV", "section": "30.2.4.2", "title": "Verbs amb *i* consonàntica en formes del present d'indicatiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_2_4_2"}, {"gram": "GNV", "section": "30.2.4.4", "title": "Els participis forts", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_2_4_4"}, {"gram": "GNV", "section": "23.2.2", "title": "Els pronoms no reflexius de tercera persona", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_2_2"}, {"gram": "GVB", "section": "19.2.7", "title": "L'ús de l'article definit davant d'infinitius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=19_2_7"}, {"gram": "GVB", "section": "27.2.2", "title": "Els pronoms no reflexius de tercera persona", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_2_2"}, {"gram": "GVB", "section": "39.2.2", "title": "El temps, l'aspecte i el mode", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=39_2_2"}, {"gram": "GVB", "section": "40.3", "title": "Perífrasis de gerundi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=40_3"}]}},
  {"type": "c1_mor_concordanca_temporal", "lesson": {"intro": "Aprendràs a encadenar correctament els temps verbals en les condicionals, les temporals i les completives, i a usar amb criteri les formes en *-ra*, *-ria* i *-ss*.", "blocks": [{"title": "Temps absoluts i relatius", "text": "Uns temps situen l'acció respecte al **moment en què parlem** (present, passat, futur); uns altres, respecte a **un altre moment** del passat. Quan traslladem un enunciat al passat, el present passa a **imperfet** (simultaneïtat), el passat a **plusquamperfet** (anterioritat) i el futur a **condicional** (posterioritat). És la base de la **concordança temporal**.", "table": {"head": ["valor en el passat", "temps", "exemple"], "rows": [["simultaneïtat", "imperfet", "*Em va dir que el pare **dormia**.*"], ["anterioritat", "plusquamperfet", "*Li vaig dir que la vespra **havíem anat** al teatre.*"], ["posterioritat", "condicional", "*Ens va assegurar que l'endemà **enviaria** la carta.*"]]}}, {"title": "Les tres condicionals", "text": "Amb ***si***, la **real** porta present d'indicatiu en la pròtasi i futur (o imperatiu, o present habitual) en la principal. La **irreal** combina imperfet de subjuntiu i condicional. La **irreal de passat**, plusquamperfet de subjuntiu i condicional perfet. El **condicional mai no va darrere de *si***. L'imperfet d'indicatiu en la pròtasi (*si parlàvem*) és possible, però molt formal.", "table": {"head": ["classe", "pròtasi", "apòdosi"], "rows": [["real", "*Si estudie més,*", "*aprovaré.*"], ["irreal", "*Si estudiara més,*", "*aprovaria.*"], ["irreal de passat", "*Si haguera estudiat més,*", "*hauria* (o *haguera*) *aprovat.*"]]}, "watch": [{"wrong": "Si tindria temps, t'ajudaria.", "right": "Si tinguera temps, t'ajudaria."}, {"wrong": "Si vingues demà, avisa'm.", "right": "Si vens demà, avisa'm."}]}, {"title": "Formes en *-ra*, *-ria* i *-ss*", "text": "L'**imperfet de subjuntiu** té formes en ***-ra*** (*cantara*, majoritàries en valencià) i en ***-s*** (*cantés* o *cantàs*), totes correctes; igualment, el plusquamperfet: *haguera* o *hagués cantat*. En l'apòdosi, el **condicional perfet** admet *hauria* o ***haguera*** *fet*. Fora d'això, les formes en *-ra* només conserven valor de condicional en usos fixats de *ser* (*fora bo* = *seria bo*).", "table": {"head": ["temps", "formes vàlides"], "rows": [["imperfet de subjuntiu", "*cantara* / *cantés* / *cantàs*; *batera* / *batés*; *sentira* / *sentís*"], ["plusquamperfet de subjuntiu", "*haguera cantat* / *hagués cantat*"], ["condicional perfet", "*hauria cantat* / *haguera cantat*"], ["condicional simple", "*cantaria* (no **cantara*)"]]}}, {"title": "Temporals: *quan* i companyia", "text": "Si la temporal es referix al **futur**, la GNV admet el **present de subjuntiu** (el més habitual hui) i el **futur** (l'ús més tradicional): *quan acabem* o *quan acabarem*. Si expressa un fet **habitual**, present d'indicatiu. Amb *abans que* i *fins que*, sempre subjuntiu. En el passat, la posterioritat admet imperfet de subjuntiu o condicional.", "examples": ["**Quan acabem** (o **acabarem**) la faena, farem un viatge.", "**Així que arribe** Conxa, ens n'anirem.", "**Quan fa** bon temps, sopem a la terrassa. (habitual)", "**Abans que** li ho **demanara**, ja ho havia fet."]}, {"title": "Les completives en subjuntiu", "text": "Quan el verb principal exigix **subjuntiu** (voluntat, desig, sentiment, possibilitat), el temps de la subordinada depén del de la principal. Principal en **present** o futur → **present** (o perfet) de subjuntiu; principal en **passat** o condicional → **imperfet** (o plusquamperfet) de subjuntiu. I recorda que la conjunció ***que*** **no s'elidix** amb els verbs de voluntat.", "table": {"head": ["principal", "subordinada", "exemple"], "rows": [["present", "present de subjuntiu", "*Vull que vingues.*"], ["present", "perfet de subjuntiu", "*Espere que t'ho hages passat bé.*"], ["passat", "imperfet de subjuntiu", "*Volia que vingueres.*"], ["passat", "plusquamperfet de subjuntiu", "*El preocupava que no li hagueren dit res.*"]]}, "watch": [{"wrong": "Volia que vindries amb nosaltres.", "right": "Volia que vingueres (o vinguesses) amb nosaltres."}]}], "remember": ["Real: *si* + present → futur; irreal: *si* + imperfet de subjuntiu → condicional.", "Irreal de passat: *si haguera estudiat* → *hauria* (o *haguera*) *aprovat*.", "Mai condicional darrere de *si*: *si tinguera*, no **si tindria*.", "*Quan acabem* i *quan acabarem* són correctes; hui el subjuntiu és més habitual.", "Principal en passat → imperfet de subjuntiu: *Volia que vingueres*.", "*Cantara*, *cantés* i *cantàs* són formes vàlides de l'imperfet de subjuntiu."], "sources": [{"gram": "GNV", "section": "28.2.1", "title": "El temps", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_2_1"}, {"gram": "GNV", "section": "28.3", "title": "El mode", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_3"}, {"gram": "GNV", "section": "28.4.1", "title": "Els temps verbals d'indicatiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_4_1"}, {"gram": "GNV", "section": "28.4.2", "title": "Els temps verbals de subjuntiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_4_2"}, {"gram": "GNV", "section": "28.5", "title": "Precisions sobre l'ús de l'indicatiu i el subjuntiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_5"}, {"gram": "GNV", "section": "29.5", "title": "Precisions sobre el polimorfisme verbal", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=29_5"}, {"gram": "GNV", "section": "34.5.1", "title": "Les conjuncions completives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_5_1"}, {"gram": "GNV", "section": "34.5.2", "title": "Les conjuncions condicionals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_5_2"}, {"gram": "GNV", "section": "34.5.7", "title": "Les conjuncions temporals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_5_7"}, {"gram": "GVB", "section": "39.2.2", "title": "El temps, l'aspecte i el mode", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=39_2_2"}, {"gram": "GVB", "section": "41.4.1", "title": "Les conjuncions completives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_4_1"}, {"gram": "GVB", "section": "41.4.2", "title": "Les conjuncions condicionals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_4_2"}, {"gram": "GVB", "section": "41.4.7", "title": "Les conjuncions temporals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_4_7"}]}}
]$data$::jsonb) AS l(type text, lesson jsonb)
WHERE r.category = 'morfosintaxi' AND r.difficulty = 'C1' AND r.type = l.type;
